(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.badge":"संस्करण 1.5.0 मौजूदा रिलीज़ है","hero.headline":"<span class=\"hl-muted\">आत्मविश्वास से दिखें।</span> <span class=\"hl-bright\">स्क्रिप्ट पर टिके रहें।</span>","hero.sub":"आपके कंप्यूटर के लिए एक टेलीप्रॉम्प्टर, जो असली इंसानी रफ़्तार से पढ़ता है — प्रति सेकंड अक्षरों में, या आपके ट्रैक के BPM पर — और स्क्रिप्ट में लिखे हर ठहराव को चिह्नित करता है।","hero.chipDesktop":"डेस्कटॉप ऐप","hero.chipLanguages":"18 भाषाएँ","hero.chipNoAccount":"कोई खाता नहीं","what.is.title":"यह क्या है","what.is.lead":"कैमरे पर स्क्रिप्ट पढ़ने का मतलब अक्सर होता है बहुत तेज़ या बहुत धीमा स्क्रॉल, भूला हुआ ठहराव, और एक दूसरी स्क्रीन जो एक पंक्ति पीछे चल रही हो।","what.is.body":"Freally Teleprompt आपके कंप्यूटर के लिए एक टेलीप्रॉम्प्टर है। जो स्क्रिप्ट आपको भेजी गई है उसे खोलें, गति को अक्षर प्रति सेकंड में या अपने ट्रैक के BPM पर सेट करें, और यह असली इंसानी रफ़्तार से चलता है — आपका लिखा हर ठहराव स्क्रिप्ट में चिह्नित, और हर स्क्रीन एक ही शब्द पर।","what.title":"यह क्या करता है","features.pace.title":"पढ़ने की असली रफ़्तार","features.pace.body":"गति प्रति सेकंड अक्षरों में तय करें, या किसी ट्रैक के साथ ताल में पढ़ने के लिए 20 से 250 तक BPM में — 1 से 10 तक का कोई मनमाना डायल नहीं।","features.pauses.title":"ठहराव जो दिखते हैं","features.pauses.body":"छोटे ठहराव के लिए -- टाइप करें, या तीन सेकंड रुकने के लिए --3। हर एक संपादक में एक चिप बन जाता है, और पाठ के वहाँ पहुँचते ही रोशन हो जाता है।","features.screens.title":"हर स्क्रीन एक ही शब्द पर","features.screens.body":"अक्षरों में गिनने वाला एक ही इंजन आपके पूर्वावलोकन, प्रस्तुतकर्ता के प्रोजेक्टर — ज़रूरत हो तो प्रॉम्प्टर काँच के लिए उलटा — और आपके अपने नेटवर्क के फ़ोन को चलाता है, इसलिए वे कभी एक-दूसरे से अलग नहीं भटकते।","features.import.title":"वह फ़ाइल खोलें जो आपको भेजी गई","features.import.body":"Word, RTF, PDF, सादा पाठ और Markdown फ़ाइलों को साफ़ प्रॉम्प्टर पाठ के रूप में आयात करें, साथ में उस हर चीज़ की रिपोर्ट जो यह नहीं ला सका।","features.markers.title":"अपना रास्ता ढूँढें","features.markers.body":"# से शुरू होने वाली पंक्ति जंप सूची में एक खंड-चिह्न बन जाती है, और साथ में हैं खोजें और बदलें और शब्दों की लाइव गिनती।","features.timing.title":"समय पर पढ़ें","features.timing.body":"अपना टेम्पो थपथपाएँ, आरंभिक गिनती के साथ क्लिक सुनें, ताल और मात्राएँ देखें, और खंड-दर-खंड समय की रिपोर्ट के लिए रिहर्सल करें।","features.control.title":"पेडल, रिमोट और हॉटकी","features.control.body":"हर कमांड की एक कुंजी है जिसे आप बदल सकते हैं। फ़ुट पेडल और प्रेज़ेंटर रिमोट किसी भी कुंजी की तरह बाँधे जा सकते हैं, और कोई कुंजी ऐप के सामने न होने पर भी काम कर सकती है।","features.writing.title":"लिखते समय मदद","features.writing.body":"ऐप के भीतर की शब्द-सूचियों से 18 भाषाओं में ऑटोकम्प्लीट, और अंग्रेज़ी में डिक्टेशन: बोलिए, और वह स्क्रिप्ट में लिख दिया जाता है।","features.private.title":"आपका, आपके कंप्यूटर पर","features.private.body":"न कोई खाता, न टेलीमेट्री, न क्लाउड। स्क्रिप्ट आपके कंप्यूटर पर सादी फ़ाइलें हैं, और ऐप इंटरनेट से सिर्फ़ एक बात पूछता है: क्या कोई नया संस्करण है।","ladder.title":"2.0 की ओर रास्ता","ladder.intro":"अब तक की हर रिलीज़, फिर 2.0 के रास्ते पर नियोजित कदम। किसी कदम को उसका संस्करण नंबर तब मिलता है जब वह रिलीज़ होता है, और योजना बदल सकती है।","ladder.rung.v0.100.0":"नींव: ऐप Windows, macOS और Linux पर चलता है, आपसे अपना लाइसेंस स्वीकार करने को कहता है, और Freally Capture से आए अक्षर-आधारित इंजन से स्क्रिप्ट स्क्रॉल करता है।","ladder.rung.v0.200.0":"स्टैंडअलोन टेलीप्रॉम्प्टर: स्क्रिप्ट लाइब्रेरी, ठहराव चिप, प्रस्तुतकर्ता के लिए दर्पण-उलटाव वाला प्रोजेक्टर, आपके अपने नेटवर्क के फ़ोन तक मिरर, असली प्लेबैक नियंत्रण, BPM पर गति और ज़ोर से पढ़ना।","ladder.rung.v0.300.0":"ऑफ़लाइन ऑटोकम्प्लीट: टाइप करते समय यह शब्द और आम वाक्यांश पूरे करता है, सभी 18 भाषाओं में, ऐप के भीतर की शब्द-सूचियों से।","ladder.rung.v1.0.0":"पहली पूरी रिलीज़: एक मिनट का स्वागत परिचय, कीबोर्ड और स्क्रीन-रीडर के लिए सुधार, आपके सिस्टम के साथ चलने वाली थीम, और ऐसे अपडेट जो आपकी हाँ के बाद ही इंस्टॉल होते हैं।","ladder.rung.v1.1.0":"बोलकर अपनी स्क्रिप्ट लिखें: आपके कंप्यूटर पर चलने वाला डिक्टेशन, जिसे कुछ भी प्रशिक्षित नहीं करना पड़ता।","ladder.rung.v1.2.0":"डिक्टेशन, पूरा: ठीक-ठाक रिकॉर्ड बटन, शब्द जो वहीं पहुँचते हैं जहाँ आपका कर्सर है, और पूर्ववत करना जो आपकी कही एक बात वापस लेता है।","ladder.rung.v1.3.0":"समय पर पढ़ना: आपकी प्रस्तुति से मेल खाने के लिए थपथपाकर तय किया गया टेम्पो, मेट्रोनोम, ताल और मात्रा काउंटर, समय की रिपोर्ट के साथ रिहर्सल, और ऐसे लेबल जिनमें पढ़ने का कोई समय नहीं लगता।","ladder.rung.v1.4.0":"स्क्रिप्ट को अंदर लाना: Word, RTF, PDF, टेक्स्ट और Markdown फ़ाइलों का आयात, जंप सूची के साथ खंड-चिह्न, खोजें और बदलें, और स्क्रिप्ट के आँकड़े।","ladder.rung.v1.5.0":"कमरे में मौजूद कोई भी चीज़ इसे चला सकती है: फ़ुट पेडल और प्रेज़ेंटर रिमोट, ऐसी कुंजियाँ जो ऐप के सामने न होने पर भी काम करती हैं, और हर कमांड का नक्शा जिसके बंधन बदले जा सकते हैं।","ladder.rung.rig":"रिग के लिए बना: ऊपर लगे काँच के लिए ऊर्ध्वाधर उलटाव, लेंस और सुरक्षित-मार्जिन गाइड, बीते और बचे समय का डिस्प्ले, और दूर से पढ़ने के लिए प्रीसेट।","ladder.rung.takes":"कोई टेक कभी न खोए: क्रैश के बाद बिना सहेजे बदलावों की वापसी, हर स्क्रिप्ट के साथ चलने वाली सेटिंग्स, स्थानीय संस्करण इतिहास, और काग़ज़ी बैकअप के लिए PDF में निर्यात।","ladder.rung.writing":"लिखने में मदद: तुकांत शब्द खोजने वाला, हर पंक्ति के शब्दांशों की गिनती, ज़बान लड़खड़ाने वाले शब्दों की जाँच और सुझाए गए ठहराव — शब्दकोशों से, बिना किसी मॉडल के।","ladder.rung.remote":"इसे कहीं से भी चलाएँ: फ़ोन के आकार का नियंत्रण पेज, साथ में उस डेस्क के लिए MIDI और OSC जिसे आप पहले से चलाते हैं — सिर्फ़ आपके अपने नेटवर्क पर, और डिफ़ॉल्ट रूप से बंद।","ladder.rung.show":"पूरा शो चलाएँ: हर आइटम की अवधि वाले रनडाउन, एक से ज़्यादा प्रॉम्प्टर आउटपुट, और फ़्लोर के लिए बड़ा काउंटडाउन और क्यू-लाइट डिस्प्ले।","ladder.rung.record":"प्रॉम्प्ट करते हुए रिकॉर्ड करें: स्क्रिप्ट चलते समय वेबकैम से टेक, या सिर्फ़ ऑडियो, जिसमें आपके खंड-चिह्न फ़ाइल में अध्यायों के रूप में लिखे जाते हैं।","ladder.rung.languages":"हर स्क्रिप्ट, हर भाषा: अलग-अलग शब्दों पर ज़ोर, पंक्ति के ऊपर फ़ुरिगाना, अरबी के दाएँ-से-बाएँ लेखन में निखार, और ऊपर से नीचे लिखी जाने वाली जापानी और चीनी।","ladder.rung.v2.0.0":"संस्करण 2.0: ऊपर का सब कुछ, Windows, macOS और Linux पर।","ladder.note":"“पूरा” का मतलब है रिलीज़ और टैग किया गया। फिर भी, यह साइट कोई डाउनलोड नहीं देती।","honest.title":"वे बातें जिन्हें ज़्यादातर साइटें सबसे नीचे रखती हैं","honest.model.title":"डिक्टेशन एक स्पीच मॉडल का उपयोग करता है","honest.model.body":"डिक्टेशन ऐप का इकलौता हिस्सा है जो मशीन लर्निंग का उपयोग करता है: Vosk, एक ओपन-सोर्स वाक्-पहचानकर्ता, ऐप के भीतर लगभग 40 MB के एक छोटे अंग्रेज़ी मॉडल के साथ। यह आपके कंप्यूटर पर चलता है, कुछ भी अपलोड या डाउनलोड नहीं करता, सिर्फ़ अंग्रेज़ी समझता है, और जब तक आप इसे चालू न करें, बंद रहता है। बाक़ी सब कुछ साधारण कोड और शब्द-सूचियाँ हैं।","honest.update.title":"यह इंटरनेट से एक ही सवाल पूछता है","honest.update.body":"हर बार शुरू होने पर ऐप GitHub से पूछता है कि क्या कोई नया संस्करण है। इस अनुरोध में न कोई स्क्रिप्ट होती है, न सेटिंग्स, न कोई पहचान-सूचक, और आपकी हाँ के बिना कुछ भी इंस्टॉल नहीं होता। बाक़ी सब कुछ बिना किसी कनेक्शन के काम करता है।","honest.voice.title":"यह आपकी आवाज़ का अनुसरण नहीं करता","honest.voice.body":"कुछ टेलीप्रॉम्प्टर आपको पढ़ते हुए सुनकर स्क्रॉल करते हैं। Freally Teleprompt 1.5.0 आपकी तय की गई गति पर स्क्रॉल करता है, और जब पढ़ने की लय बदलती है तो आप, कोई कुंजी या पेडल नियंत्रण सँभाल लेते हैं। आवाज़ का अनुसरण करने वाला एक मोड 1.0.0 में आज़माया गया था और 1.1.0 में हटा दिया गया।","honest.downloads.title":"इस साइट पर कोई डाउनलोड नहीं है","honest.downloads.body":"न कोई डाउनलोड लिंक, न बटन, न बीटा। सोर्स कोड भी निजी है।","site.tagline":"आत्मविश्वास से दिखें। स्क्रिप्ट पर टिके रहें।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © Mike Weaver. आज उपयोग के लिए मुफ़्त; भविष्य के संस्करण बेचे जा सकते हैं। ओपन सोर्स नहीं।","footer.yours":"आपकी स्क्रिप्ट आपकी हैं। वे आपके कंप्यूटर पर रहती हैं, और ऐप का लेखक उन्हें कभी प्राप्त नहीं करता, न सहेजता है, न आगे भेजता है।","featuresPage.lead":"Windows, macOS और Linux के लिए एक टेलीप्रॉम्प्टर, जो असली इंसानी रफ़्तार से पढ़ता है, हर स्क्रीन को एक ही शब्द पर रखता है, और वह स्क्रिप्ट खोलता है जो आपको भेजी गई थी।","featuresPage.version":"यह पेज Freally Teleprompt 1.5.0, यानी रिलीज़ हो चुके संस्करण, का वर्णन करता है: इस पर लिखा सब कुछ 1.5.0 में है, और जो अभी सिर्फ़ योजना में है, वह इस पर नहीं है।","featuresPage.numbers.intro":"हर आँकड़ा वही है जो संस्करण 1.5.0 करता है, उसके कोड से गिना गया। कुछ भी बढ़ाकर गोल नहीं किया गया।","featuresPage.numbers.paces":"गति तय करने के तरीके: प्रति सेकंड अक्षर या BPM","featuresPage.numbers.bpm":"BPM: वह दायरा जिसमें यह ताल पर पढ़ता है","featuresPage.numbers.formats":"फ़ाइलों के प्रकार जिन्हें यह आयात करता है: Word, RTF, PDF, सादा पाठ और Markdown","featuresPage.numbers.systems":"ऑपरेटिंग सिस्टम: Windows, macOS और Linux","featuresPage.numbers.languages":"भाषाएँ, ऐप में और उसके ऑटोकम्प्लीट में","featuresPage.numbers.words":"शब्द इसकी ऑटोकम्प्लीट सूचियों में, साथ में 344,891 वाक्यांश","featuresPage.numbers.accounts":"खाते जो बनाने पड़ते हैं","featuresPage.numbers.model":"स्पीच मॉडल, डिक्टेशन के लिए: आपके कंप्यूटर पर, और जब तक आप चालू न करें, बंद","featuresPage.numbers.price":"आज की क़ीमत","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Freally Teleprompt 1.5.0 जो कुछ भी करता है, वह आज सबके लिए मुफ़्त है: न कोई सशुल्क स्तर, न सदस्यता, न खाता, और न कोई ट्रायल जो ख़त्म हो जाए।","featuresPage.cards.title":"संस्करण 1.5.0 क्या करता है","featuresPage.cards.pace.title":"पढ़ने की असली रफ़्तार","featuresPage.cards.pace.body":"प्रति सेकंड अक्षर, या किसी ट्रैक पर पढ़े जाने वाले बोल और छंदों के लिए 20 से 250 तक BPM। स्क्रिप्ट चलते समय दोनों में से किसी को भी बदलें, और स्क्रॉल तुरंत नई गति पकड़ लेता है।","featuresPage.cards.pauses.title":"ठहराव चिप","featuresPage.cards.pauses.body":"छोटे ठहराव के लिए -- टाइप करें, या N सेकंड रुकने के लिए --N। हर एक ऐसी चिप है जिसे कर्सर बाँट नहीं सकता, पाठ के वहाँ पहुँचते ही वह रोशन हो जाती है, और ज़ोर से पढ़ना उसे असली चुप्पी में बदल देता है।","featuresPage.cards.engine.title":"हर स्क्रीन एक ही शब्द पर","featuresPage.cards.engine.body":"पूर्वावलोकन, प्रोजेक्टर और आपके नेटवर्क के डिवाइस, अक्षरों में गिनने वाले एक ही इंजन का पालन करते हैं, इसलिए अलग-अलग पाठ आकार पर भी वे इस पर सहमत रहते हैं कि कौन-सा शब्द पढ़ा जा रहा है।","featuresPage.cards.projector.title":"प्रस्तुतकर्ता के लिए प्रोजेक्टर","featuresPage.cards.projector.body":"किसी भी डिस्प्ले पर पूरी स्क्रीन, बीम-स्प्लिटर काँच के लिए दर्पण-छवि में, और पढ़ने वाले व्यक्ति के लिए अपने प्लेबैक नियंत्रण और कुंजियों के साथ।","featuresPage.cards.mirror.title":"फ़ोन और टैबलेट तक मिरर","featuresPage.cards.mirror.body":"जब तक आप चालू न करें, बंद। एक लिंक और QR कोड आपके अपने नेटवर्क के किसी भी ब्राउज़र में स्क्रिप्ट खोलते हैं: केवल-पढ़ने के लिए, ऐसी कुंजी के साथ जो हर बार ऐप शुरू होने पर बदल जाती है।","featuresPage.cards.import.title":"Word, RTF, PDF, टेक्स्ट और Markdown आयात करें","featuresPage.cards.import.body":"अनुच्छेदों को बनाए रखते हुए साफ़ प्रॉम्प्टर पाठ, और एक रिपोर्ट जो गिनती है कि क्या नहीं आ सका — तस्वीरें, पाद-टिप्पण, टिप्पणियाँ। आपके कहे बिना कुछ भी सहेजा नहीं जाता।","featuresPage.cards.markers.title":"खंड-चिह्न, खोजें और बदलें","featuresPage.cards.markers.body":"# से शुरू होने वाली पंक्ति सीक बार पर और जंप सूची में एक चिह्न होती है। खोजें और बदलें अक्षर-आकार या पूरे शब्दों का मिलान करता है, और एक ही बार दबाने में पूर्ववत हो जाता है।","featuresPage.cards.timing.title":"टेम्पो, क्लिक और ताल","featuresPage.cards.timing.body":"BPM को अपनी प्रस्तुति के अनुसार ढालने के लिए अपना टेम्पो थपथपाएँ, आरंभिक गिनती के साथ क्लिक सुनें, और ताल व मात्रा को स्क्रीन पर और सीक बार पर रेखाओं के रूप में देखें।","featuresPage.cards.rehearsal.title":"रिहर्सल और समय की रिपोर्ट","featuresPage.cards.rehearsal.body":"पूरा पढ़ें और हर खंड का नियोजित समय असली समय के सामने देखें, और वह गति भी जिस पर आपने सचमुच पढ़ा। यह सिर्फ़ समय दर्ज करता है — न माइक्रोफ़ोन, न ऑडियो।","featuresPage.cards.skip.title":"ऐसे लेबल जिनमें कोई समय नहीं लगता","featuresPage.cards.skip.body":"मुखड़ा, [अंतरा 1] या ## ब्रिज को ऐसे शब्दों के रूप में चिह्नित करें जिन्हें आप प्रस्तुत नहीं करते: वे स्क्रीन पर धुँधले दिखते रहते हैं और पढ़ने का कोई समय नहीं लेते, इसलिए आपके बोल ताल पर बने रहते हैं।","featuresPage.cards.control.title":"शॉर्टकट, पेडल और हॉटकी","featuresPage.cards.control.body":"हर कमांड का खोजने योग्य नक्शा, टकरावों पर निशान के साथ। पेडल और रिमोट किसी भी कुंजी की तरह बाँधे जा सकते हैं, और कोई कुंजी तब भी काम कर सकती है जब कोई दूसरा ऐप सामने हो।","featuresPage.cards.writing.title":"ऑटोकम्प्लीट, डिक्टेशन और ज़ोर से पढ़ना","featuresPage.cards.writing.body":"ऐप के भीतर की सूचियों से 18 भाषाओं में शब्दों और वाक्यांशों के सुझाव, आपके कंप्यूटर पर चलने वाला अंग्रेज़ी डिक्टेशन, और आपके सिस्टम की अपनी आवाज़ों में ज़ोर से पढ़ना।","featuresPage.cards.look.title":"आपकी दिखावट, आपकी भाषा","featuresPage.cards.look.body":"टाइपफ़ेस, आकार, मोटाई, रंग, मार्जिन, पंक्ति अंतराल और पठन रेखा, सभी स्क्रीन पर एक साथ। ऐप 18 भाषाएँ बोलता है, गहरी या हल्की थीम में।","featuresPage.cards.private.title":"न खाता, न क्लाउड","featuresPage.cards.private.body":"स्क्रिप्ट आपके कंप्यूटर पर सादी फ़ाइलें हैं, और कोई टेलीमेट्री नहीं है। इंटरनेट से ऐप का इकलौता अनुरोध नए संस्करण की जाँच है, और आपकी हाँ के बिना कुछ भी इंस्टॉल नहीं होता।","featuresPage.compare.title":"व्यावसायिक टेलीप्रॉम्प्टरों के साथ आमने-सामने","featuresPage.compare.intro":"Freally Teleprompt 1.5.0 — रिलीज़ हो चुका संस्करण, जिसे आप आज इस्तेमाल कर सकते हैं — छह व्यावसायिक टेलीप्रॉम्प्टर ऐप्स के बगल में। किसी दूसरे उत्पाद का हर ख़ाना उसके निर्माता के अपने पेजों या ऐप-स्टोर लिस्टिंग से लिया गया है, 2 अक्टूबर 2026 को जाँचा गया, और क़ीमतें अक्टूबर 2026 के अनुसार अमेरिकी डॉलर में हैं।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.price":"क़ीमत (USD, अक्टूबर 2026)","featuresPage.compare.freeToday":"आज मुफ़्त","featuresPage.compare.unit.perMonth":"प्रति माह","featuresPage.compare.unit.perYear":"प्रति वर्ष","featuresPage.compare.unit.once":"एक बार","featuresPage.compare.unit.onSale":"छूट पर; आमतौर पर $99","featuresPage.compare.row.systems":"Windows, macOS और Linux के लिए डेस्कटॉप ऐप","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.legend.partly":"आंशिक","featuresPage.compare.note.browser":"और वेब ब्राउज़र में","featuresPage.compare.row.noAccount":"बिना खाता बनाए उपयोग करें","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.legend.unknown":"सत्यापित नहीं","featuresPage.compare.row.offline":"बिना इंटरनेट कनेक्शन के काम करता है","featuresPage.compare.note.updateCheck":"सिर्फ़ अपडेट जाँच ऑनलाइन जाती है","featuresPage.compare.note.afterRegistration":"ऑनलाइन पंजीकरण के बाद","featuresPage.compare.row.import":"Word और PDF फ़ाइलें खोलता है","featuresPage.compare.note.ourFormats":"RTF, सादा पाठ और Markdown भी","featuresPage.compare.note.wordIos":"Word सिर्फ़ iPhone और iPad पर","featuresPage.compare.note.textRtf":"सिर्फ़ सादा पाठ और RTF","featuresPage.compare.row.bpm":"स्क्रॉल की गति संगीत के टेम्पो (BPM) पर तय करता है","featuresPage.compare.row.pauses":"स्क्रिप्ट में लिखे समयबद्ध ठहराव","featuresPage.compare.row.mirror":"प्रॉम्प्टर काँच के लिए उलटा (दर्पण) पाठ","featuresPage.compare.row.devices":"स्क्रिप्ट दूसरे डिवाइसों पर दिखाता है","featuresPage.compare.note.ownNetwork":"आपके अपने नेटवर्क पर, ब्राउज़र में","featuresPage.compare.note.portal":"निर्माता के पोर्टल के ज़रिए, ऑनलाइन","featuresPage.compare.note.internet":"इंटरनेट के ज़रिए","featuresPage.compare.note.btWifi":"ब्लूटूथ, वाई-फ़ाई या इंटरनेट के ज़रिए","featuresPage.compare.note.displayOrLan":"दूसरा डिस्प्ले, या नेटवर्क पर कोई दूसरा डिवाइस","featuresPage.compare.note.secondMonitor":"दूसरा मॉनिटर; टैबलेट के लिए दूसरे ऐप चाहिए","featuresPage.compare.row.remotes":"फ़ुट पेडल और प्रेज़ेंटर रिमोट","featuresPage.compare.note.keyboardOnly":"सिर्फ़ कीबोर्ड शॉर्टकट","featuresPage.compare.row.voiceScroll":"स्क्रॉल आपकी आवाज़ का अनुसरण करता है","featuresPage.compare.note.removed":"1.1.0 में हटाया गया","featuresPage.compare.note.paidAddon":"एक सशुल्क ऐड-ऑन","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"संक्षेप में: इन सातों में से सिर्फ़ Freally Teleprompt कहता है कि वह स्क्रॉल की गति BPM से तय करता है और स्क्रिप्ट में लिखे समयबद्ध ठहरावों पर रुकता है, और यही इकलौता है जो Windows, macOS और Linux पर बिना खाते और बिना भुगतान के चलता है।","featuresPage.compare.theyWinTitle":"वे कहाँ आगे हैं","featuresPage.compare.theyWin":"जहाँ वे आगे हैं: PromptSmart, Speakflow और Teleprompter.com आपकी आवाज़ का अनुसरण करके स्क्रॉल करते हैं, और TeleScroll एक सशुल्क ऐड-ऑन के साथ ऐसा करता है; Freally Teleprompt 1.5.0 ऐसा नहीं करता। PromptSmart, Teleprompter.com और Teleprompter Pro के फ़ोन और टैबलेट ऐप हैं जो आपके पढ़ते समय वीडियो रिकॉर्ड करते हैं और आपकी स्क्रिप्ट अपने क्लाउड में रखते हैं, और Speakflow में AI लेखन टूल और रीयल-टाइम सहयोग भी है।","featuresPage.compare.asOf":"Freally Teleprompt का कॉलम संस्करण 1.5.0 है, जो रिलीज़ हो चुका है, इसलिए तालिका उसकी तुलना करती है जिसे आप आज इस्तेमाल कर सकते हैं। इसकी क़ीमत आज की है: Freally Teleprompt आज मुफ़्त है, और भविष्य के संस्करण बेचे जा सकते हैं। दूसरे उत्पाद भी बदलते हैं; यह तालिका 2 अक्टूबर 2026 की स्थिति के अनुसार है।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.engine.title":"एक इंजन, अक्षरों में गिनती","featuresPage.why.engine.body":"गति प्रति सेकंड अक्षरों में है, इसलिए पूर्वावलोकन, प्रोजेक्टर और हर फ़ोन, फ़ॉन्ट का आकार चाहे जो हो, एक ही पाठ से एक ही दर पर गुज़रते हैं। इंजन दो बार लिखा गया है, ऐप के कोर के लिए और उसके इंटरफ़ेस के लिए, और दोनों को बिल्कुल एक जैसा रखा जाता है।","featuresPage.why.import.title":"ऐसा कन्वर्टर जो बताता है कि उसने क्या छोड़ा","featuresPage.why.import.body":"आयात चुपचाप खो देने के बजाय गिनता है कि वह क्या नहीं ला सका, और छपाई वाले डैश को कभी ऐसे ठहराव में नहीं बदलता जिसे किसी ने नहीं लिखा।","featuresPage.why.isolate.title":"ख़राब फ़ाइल पढ़ना नहीं रोक सकती","featuresPage.why.isolate.body":"दस्तावेज़ समय-सीमा वाली एक अलग प्रोसेस में पढ़े जाते हैं, इसलिए कोई ख़राब PDF सिर्फ़ वही एक आयात ख़त्म करता है, प्रॉम्प्टर नहीं।","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"न खाता, न टेलीमेट्री, न क्लाउड। आपकी स्क्रिप्ट सादी टेक्स्ट फ़ाइलें हैं जिन्हें आप किसी भी एडिटर में खोल सकते हैं, और नेटवर्क मिरर आपके अपने नेटवर्क पर ही रहता है।","featuresPage.why.consent.title":"आपकी पीठ पीछे कुछ नहीं होता","featuresPage.why.consent.body":"सेटिंग्स तभी बदलती हैं जब आप “लागू करें” दबाते हैं, कोई कुंजी सिस्टम-व्यापी तभी ली जाती है जब आप कहें, और अपडेट आपकी हाँ के बाद ही इंस्टॉल होता है।","featuresPage.why.keyboard.title":"कीबोर्ड की पहुँच में","featuresPage.why.keyboard.body":"हर नियंत्रण में फ़ोकस रिंग है, डायलॉग फ़ोकस को अपने भीतर रखते हैं, सीक बार एक असली स्लाइडर है, और कम गति व कम पारदर्शिता की सिस्टम सेटिंग्स का सम्मान किया जाता है।","featuresPage.coming.title":"अभी क्या आना बाक़ी है","featuresPage.coming.intro":"साफ़-साफ़ कहा गया, क्योंकि जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। इस पेज पर सब कुछ 1.5.0 में है; उसके बाद के कदम 2.0 के रास्ते पर हैं, हर एक अपनी स्थिति के साथ चिह्नित।","featuresPage.limits.title":"1.5.0 क्या नहीं करता","featuresPage.limits.voice":"यह आपकी आवाज़ का अनुसरण करके स्क्रॉल नहीं करता: गति आप तय करते हैं, और जब पढ़ने की लय बदलती है तो कोई कुंजी या पेडल नियंत्रण सँभालता है।","featuresPage.limits.dictation":"डिक्टेशन सिर्फ़ अंग्रेज़ी समझता है; ऑटोकम्प्लीट और इंटरफ़ेस सभी 18 भाषाओं में हैं।","featuresPage.limits.phone":"कोई फ़ोन या टैबलेट ऐप नहीं है: फ़ोन नेटवर्क मिरर के ज़रिए स्क्रिप्ट दिखा सकता है, केवल-पढ़ने के लिए, पर उसे चला नहीं सकता।","featuresPage.limits.recording":"प्रॉम्प्ट करते समय यह वीडियो या ऑडियो रिकॉर्ड नहीं करता।","featuresPage.limits.wayland":"Linux पर Wayland में, किसी दूसरे ऐप के सामने होने पर काम करने के लिए तय की गई कुंजी शायद काम न करे, क्योंकि Wayland ऐप्स को सिस्टम-व्यापी कुंजियाँ लेने नहीं देता; ऐप के भीतर की कुंजियों पर कोई असर नहीं पड़ता।","featuresPage.coming.downloads":"इस साइट पर कोई डाउनलोड नहीं है, और इस पेज पर भी नहीं।","docs.intro":"Freally Teleprompt का उपयोग कैसे करें, पहली बार खोलने से लेकर रिग पर पढ़ने तक।","docs.start.title":"शुरुआत करना","docs.write.title":"स्क्रिप्ट लिखें","docs.import.title":"दस्तावेज़ आयात करें","docs.find.title":"खोजें और बदलें","docs.markers.title":"खंड-चिह्न","docs.pauses.title":"ठहराव चिप","docs.pacing.title":"गति: प्रति सेकंड अक्षर या BPM","docs.tempo.title":"टेम्पो, ताल और क्लिक","docs.rehearsal.title":"रिहर्सल और समय की रिपोर्ट","docs.skip.title":"वे शब्द जो आप नहीं गाते","docs.playback.title":"प्लेबैक और ट्रांसपोर्ट नियंत्रण","docs.shortcuts.title":"शॉर्टकट, पेडल और हॉटकी","docs.countdown.title":"शुरुआती काउंटडाउन","docs.projector.title":"प्रोजेक्टर","docs.mirror.title":"नेटवर्क मिरर","docs.readAloud.title":"ज़ोर से पढ़ना","docs.autocomplete.title":"ऑटोकम्प्लीट","docs.dictation.title":"डिक्टेशन","docs.settings.title":"दिखावट, भाषाएँ और सेटिंग्स","docs.access.title":"परिचय और सुलभता","docs.problems.title":"समस्याएँ और अपडेट","docs.privacy.title":"निजता और नेटवर्क","docs.start.p1":"Freally Teleprompt, Windows, macOS और Linux के लिए एक टेलीप्रॉम्प्टर है — प्रस्तुतकर्ताओं, स्ट्रीमरों, पॉडकास्टरों, अभिनेताओं, गायकों और रैपरों के लिए। यह एक ही विंडो में खुलता है — आपकी स्क्रिप्ट, संपादक, पूर्वावलोकन और प्रोजेक्टर के नियंत्रण — और इसके लिए किसी खाते की ज़रूरत नहीं।","docs.start.p2":"पहली बार खुलने पर यह अपना लाइसेंस अनुबंध दिखाता है। अंत तक स्क्रॉल करें, फिर “मैं सहमत हूँ” या “अस्वीकार करें और बाहर निकलें” चुनें। जब तक आप सहमत न हों, ऐप का उपयोग नहीं किया जा सकता; आपका जवाब याद रखा जाता है, और आपसे दोबारा तभी पूछा जाता है जब अनुबंध बदलता है।","docs.start.p3":"इसके बाद एक मिनट का परिचय संपादक, गति के नियंत्रण और प्रोजेक्टर दिखाता है। कोई स्क्रिप्ट टाइप या पेस्ट करें, अपनी गति तय करें और “चलाएँ” दबाएँ।","docs.start.p4":"इस साइट पर कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","docs.write.p1":"स्क्रिप्ट .ftscript फ़ाइलें होती हैं: एक ही फ़ोल्डर में सादा पाठ, जिसे किसी भी टेक्स्ट एडिटर में पढ़ा जा सकता है। उन्हें बनाने, खोलने, नाम बदलने और हटाने के लिए टूलबार पर “स्क्रिप्ट” खोलें। हाल की सूची आपको उस पर वापस ले जाती है जिस पर आप काम कर रहे थे, टाइप करते समय सब कुछ सहेजा जाता है, और ऐप वही स्क्रिप्ट फिर से खोलता है जो आपने पिछली बार खोली थी।","docs.write.p2":"संपादक में टाइप करें या कहीं से भी पेस्ट करें। पढ़ने के समय के अनुमान के नीचे, शब्दों और अक्षरों की लाइव गिनती दिखाती है कि आप असल में क्या प्रस्तुत करेंगे — छोड़े गए लेबल और ठहराव-चिह्न नहीं गिने जाते — और एक चेतावनी हर उस पंक्ति को चिह्नित करती है जो इतनी लंबी हो कि पूरा अनुच्छेद बन जाए।","docs.import.p1":"टूलबार पर “आयात” दबाएँ और कोई Word दस्तावेज़ (.docx), RTF, PDF, सादा पाठ फ़ाइल या Markdown फ़ाइल चुनें। कुछ भी सहेजे जाने से पहले आप तैयार हुआ पाठ और एक रिपोर्ट देखते हैं।","docs.import.p2":"अनुच्छेद बने रहते हैं; बोल्ड, फ़ॉन्ट और रंग सादे कर दिए जाते हैं, क्योंकि प्रॉम्प्टर एक ही टाइपफ़ेस दिखाता है। घुमावदार उद्धरण-चिह्न, लंबे डैश और एलिप्सिस सादे बन जाते हैं, और किसी पुरानी एन्कोडिंग में सहेजी गई फ़ाइल सही पढ़ी जाती है, और रिपोर्ट यह बताती है।","docs.import.p3":"तस्वीरें, पाद-टिप्पण, टिप्पणियाँ, शीर्षलेख और पादलेख, लिंक पते और अंतर्निहित वस्तुएँ गिनी और सूचीबद्ध की जाती हैं, कभी चुपचाप गिराई नहीं जातीं। PDF में ऐसी कोई संरचना नहीं होती, इसलिए PDF के लिए रिपोर्ट कहती है कि वह बता नहीं सकी।","docs.import.p4":"स्क्रिप्ट को नाम दें — फ़ाइल से एक नाम सुझाया जाता है — और “आयात करें” दबाएँ। वह आपकी लाइब्रेरी में जुड़ जाती है और खुल जाती है, और पहले से मौजूद किसी स्क्रिप्ट को कभी ओवरराइट नहीं करती। Markdown के शीर्षक # पंक्तियों के रूप में आते हैं, इसलिए Markdown स्क्रिप्ट अपने खंड-चिह्नों के साथ आती है।","docs.import.p5":"छपाई वाला डैश एक साधारण हाइफ़न बन जाता है, और ऐसे दो डैश कभी ठहराव नहीं बनते, इसलिए आयात किया गया नाटक ऐसे ठहरावों से भरा नहीं आता जिन्हें किसी ने नहीं लिखा। असली ठहराव-चिह्नों के साथ आपकी लिखी टेक्स्ट फ़ाइल उन्हें बनाए रखती है।","docs.find.p1":"खुली स्क्रिप्ट में खोजने के लिए Ctrl+F दबाएँ, या टूलबार पर “खोजें”। टाइप करते समय मिलानों की गिनती अपडेट होती रहती है; Enter अगले मिलान पर ले जाता है और Shift+Enter पिछले पर, और किसी भी सिरे पर पहुँचकर खोज घूमकर दूसरे सिरे से जारी रहती है।","docs.find.p2":"“अक्षर-आकार का मिलान करें” और “केवल पूरे शब्द” खोज को सीमित करते हैं, और आप जो टाइप करते हैं वह अक्षरशः खोजा जाता है। “बदलें” मौजूदा मिलान को बदलता है और “सभी बदलें” हर मिलान को; दोनों एक ही Ctrl+Z से पूर्ववत हो जाते हैं।","docs.markers.p1":"किसी पंक्ति को # से शुरू करें — # अंतरा 2, # प्रश्नोत्तर, ## ब्रिज — और वह एक खंड-चिह्न बन जाती है। जो पंक्ति आपके छोड़े जाने वाले शब्दों में से कोई एक हो, जैसे [मुखड़ा], वह भी एक चिह्न है। कुछ भी सेट नहीं करना पड़ता।","docs.markers.p2":"चिह्न सीक बार के बगल में एक जंप सूची में दिखते हैं, जो बताती है कि आप किस खंड में हैं, और ख़ुद सीक बार पर रेखाओं के रूप में अंकित होते हैं। “अगला खंड” और “पिछला खंड” उन पर एक-एक करके चलते हैं; “पिछला खंड” पहले उस खंड की शुरुआत पर जाता है जिसमें आप हैं, जैसे पिछले ट्रैक वाला बटन। किसी को चुनने पर हर स्क्रीन वहाँ पहुँच जाती है, प्रोजेक्टर भी।","docs.pauses.p1":"छोटे ठहराव के लिए -- टाइप करें (एक स्पेस, दो डैश, एक स्पेस), या N सेकंड रुकने के लिए --N। हर एक संपादक में एक चिप बन जाता है: कर्सर सिर्फ़ उसके पहले या बाद में रहता है, एक Backspace उसे हटा देता है, और Shift के साथ कोई तीर कुंजी उसे पूरा चुन लेती है। सादे -- की लंबाई सेटिंग्स → पठन में तय करें।","docs.pauses.p2":"कॉपी और पेस्ट चिप को ज्यों का त्यों ले जाते हैं, और पेस्ट किए गए पाठ की स्पेसिंग ठीक कर दी जाती है ताकि हर ठहराव एक साफ़ चिप बने। स्क्रिप्ट चलते समय, पाठ के पहुँचते ही हर ठहराव रोशन होता है और स्क्रॉल उतनी देर रुका रहता है — पूर्वावलोकन, प्रोजेक्टर और नेटवर्क मिरर, तीनों पर एक जैसा।","docs.pacing.p1":"गति प्रति सेकंड अक्षरों में तय करें: पढ़ने की एक असली दर, जिसका हर स्क्रीन पालन करती है, फ़ॉन्ट का आकार चाहे जो हो। या किसी ट्रैक के साथ ताल में बोल और छंद पढ़ने के लिए BPM पर जाएँ, 20 से 250 तक।","docs.pacing.p2":"दोनों एक ही इंजन चलाते हैं, और स्क्रिप्ट चलते समय किसी को भी बदलने पर गति तुरंत नई हो जाती है।","docs.tempo.p1":"टेम्पो एक ही संख्या के ज़रिए पढ़ने की गति बनता है: एक मात्रा में आप कितने अक्षर पढ़ते हैं। सेटिंग्स → समय-निर्धारण → आपकी अपनी लय में, जिस टेम्पो पर आप प्रस्तुति देते हैं उस पर “थपथपाएँ” तीन या अधिक बार दबाएँ, फिर “यही लय अपनाएँ” चुनें; “डिफ़ॉल्ट पर लौटें” इसे पूर्ववत करता है। इसके बाद BPM बॉक्स सिर्फ़ वही टेम्पो देता है जिन तक इंजन पहुँच सकता है।","docs.tempo.p2":"BPM चालू होने पर, या क्लिक चालू होने पर, ताल और मात्रा सीक बार के ऊपर दिखते हैं और उस पर ताल-रेखाएँ अंकित होती हैं। प्रति ताल मात्राएँ, 2 से 12 तक, सेटिंग्स → समय-निर्धारण में तय करें।","docs.tempo.p3":"हर मात्रा पर एक धीमी टिक के लिए “वर्तमान लय पर क्लिक बजाएँ” पर सही का निशान लगाएँ — हर ताल की पहली मात्रा पर ऊँची टिक; शुरुआती काउंटडाउन उसकी आरंभिक गिनती बन जाता है। ऐप ध्वनि ख़ुद बनाता है और हर टिक का समय ऑडियो घड़ी से तय करता है, इसलिए वह भटकती नहीं। जब ज़ोर से पढ़ना बोल रहा हो, तब क्लिक चुप रहता है।","docs.rehearsal.p1":"ट्रांसपोर्ट के नीचे “रिहर्सल करें और मेरे पाठ का समय मापें” पर सही का निशान लगाएँ, “चलाएँ” दबाएँ और वैसे ही ज़ोर से पढ़ें जैसे असली दिन पढ़ेंगे। रुकें, पीछे जाएँ, गति बदलें: यह सब माप का हिस्सा है।","docs.rehearsal.p2":"निशान हटाते ही रिहर्सल रिपोर्ट खुल जाती है: हर खंड की एक पंक्ति, जिसमें आपकी गति पर उसमें लगने वाला समय, असल में लगा समय और दोनों का अंतर होता है। खंड आपके अनुच्छेद होते हैं, या आपके खंड-चिह्न, जब स्क्रिप्ट उनसे बँटी हो। अगर आपने किसी दूसरी गति पर पढ़ा, तो रिपोर्ट वही गति सुझाती है, और एक क्लिक उसे लागू कर देता है।","docs.rehearsal.p3":"रिहर्सल के दौरान, जैसे ही पाठ अपनी योजना से तीन सेकंड या उससे ज़्यादा पीछे या आगे होता है, एक शांत चेतावनी दिखती है। रिहर्सल सिर्फ़ समय दर्ज करता है, और कुछ नहीं: यह कोई माइक्रोफ़ोन नहीं खोलता और कोई ऑडियो नहीं रखता, और यह ज़ोर से पढ़ने के साथ एक साथ नहीं चल सकता।","docs.skip.p1":"खंडों के लेबल — मुखड़ा, अंतरा 2, ब्रिज — ऐसे पहचान-चिह्न हैं जिन्हें आप आते हुए देखते हैं पर कभी बोलते नहीं। उन्हें सेटिंग्स → समय-निर्धारण → वे शब्द जो आप नहीं गाते में लिखें, हर पंक्ति में एक। सूची ख़ाली शुरू होती है, क्योंकि यह बदल देती है कि स्क्रिप्ट का समय कैसे तय होता है।","docs.skip.p2":"जो पंक्ति सिर्फ़ एक लेबल हो, वह पूरी छोड़ दी जाती है: कोष्ठक, हैश, कोलन और अंत की संख्या को अनदेखा किया जाता है, इसलिए मुखड़ा, [अंतरा 1], ## ब्रिज और मुखड़ा: सब मेल खाते हैं। असली पंक्ति के भीतर वही शब्द सिर्फ़ ख़ुद को छोड़ता है। मिलान बड़े-छोटे अक्षरों को अनदेखा करता है और सिर्फ़ पूरे शब्दों से मेल खाता है।","docs.skip.p3":"छोड़ा गया पाठ स्क्रीन पर धुँधला दिखता रहता है, ताकि प्रस्तुतकर्ता उसे आते हुए फिर भी देख सके, और ज़ोर से पढ़ना उसे कभी नहीं बोलता। क्योंकि लेबल में कोई समय नहीं लगता, स्क्रॉल उसे तुरंत पार कर जाता है — और आपके बोल उसी ताल पर बने रहते हैं जिसके लिए आपने उन्हें लिखा था।","docs.playback.p1":"चलाएँ, रोकें, बंद करें, पीछे जाएँ और आगे जाएँ स्क्रीन पर बटन हैं; लगातार चलते रहने के लिए पीछे या आगे वाले बटन को दबाए रखें। आगे-पीछे करने के लिए माउस व्हील घुमाएँ, किसी शब्द से शुरू करने के लिए उस पर क्लिक करें, या उस बिंदु के शब्द देखने के लिए सीक बार पर होवर करें।","docs.playback.p2":"सीक बार बीता हुआ और कुल पढ़ने का समय दिखाती है, ठहराव मिलाकर। एक पठन गाइड मौजूदा शब्द को पठन रेखा पर रखती है, और आख़िरी रोशन शब्द कभी स्क्रॉल होकर नज़रों से बाहर नहीं जाता।","docs.shortcuts.p1":"टूलबार पर “शॉर्टकट” खोलें। जिस बंधन को बदलना है उसे दबाएँ, फिर मनचाही कुंजी, रिमोट या पेडल दबाएँ; Escape उसे पहले जैसा छोड़ देता है। किसी कमांड के नाम से या ख़ुद कुंजी से खोजें। अगर दो कमांड एक ही कुंजी साझा करते हैं, तो दोनों पंक्तियाँ यह बताती हैं; × से किसी एक को मिटाएँ, या “डिफ़ॉल्ट पर लौटाएँ” चुनें।","docs.shortcuts.p2":"ज़्यादातर फ़ुट पेडल और प्रेज़ेंटर रिमोट साधारण कुंजियाँ भेजते हैं, आमतौर पर F13 से F24, इसलिए वे बिना ड्राइवर और बिना सेटअप के बँध जाते हैं। बंधन भौतिक कुंजी का पालन करते हैं, उस पर छपे अक्षर का नहीं, इसलिए कीबोर्ड लेआउट बदलने पर भी बने रहते हैं।","docs.shortcuts.p3":"“कहीं भी” कॉलम आपके सिस्टम से कहता है कि कोई दूसरा ऐप सामने होने पर भी कुंजी पहुँचाए — कोई कैमरा ऐप, DAW या OBS। जब तक आप सेट न करें, कुछ भी नहीं लिया जाता, और जो कुंजी पहले से किसी दूसरे प्रोग्राम के पास है, वह यह बता देती है। Linux पर Wayland में ऐप सिस्टम-व्यापी कुंजियाँ नहीं ले सकते, और डायलॉग आपको यह बताता है।","docs.shortcuts.p4":"जब आप लिख रहे हों, तब स्पेस बार, तीर कुंजियाँ और Home सामान्य रूप से टाइप करती हैं: अकेली कुंजी अपना कमांड सिर्फ़ संपादक के बाहर चलाती है।","docs.countdown.p1":"सेटिंग्स → पठन में “शुरू होने से पहले काउंटडाउन” तय करें, और “चलाएँ” दबाने पर पहले उतने सेकंड की उलटी गिनती होती है, पूर्वावलोकन और प्रोजेक्टर पर, ताकि पहला शब्द हिलने से पहले प्रस्तुतकर्ता को एक पल मिल जाए। क्लिक चालू होने पर यही काउंटडाउन आरंभिक गिनती भी होता है।","docs.projector.p1":"“प्रोजेक्टर खोलें” दबाएँ और वह डिस्प्ले चुनें जिससे प्रस्तुतकर्ता पढ़ता है: स्क्रिप्ट उस स्क्रीन को किनारे से किनारे तक भर देती है। बीम-स्प्लिटर काँच के लिए दर्पण चालू करें, जहाँ वरना प्रतिबिंब उलटा पढ़ा जाता। प्रोजेक्टर में पढ़ने वाले व्यक्ति के लिए अपना ट्रांसपोर्ट, सीक बार और कुंजियाँ हैं।","docs.projector.p2":"पूर्वावलोकन और प्रोजेक्टर स्क्रिप्ट को एक ही चौड़ाई पर सजाते हैं और फ़िट होने के लिए उसका आकार बदलते हैं, इसलिए वे पंक्तियाँ एक ही जगहों पर तोड़ते हैं। शूट से पहले जाँच लें कि दर्पण वाला पाठ आपके अपने काँच से सही पढ़ा जा रहा है।","docs.mirror.p1":"स्क्रिप्ट को फ़ोन, टैबलेट या दूसरे लैपटॉप पर दिखाने के लिए सेटिंग्स → नेटवर्क → मेरे नेटवर्क पर मिरर करें खोलें और “मेरे नेटवर्क के उपकरणों पर स्क्रिप्ट मिरर करें” पर सही का निशान लगाएँ। “सिर्फ़ इस कंप्यूटर ही नहीं, दूसरे उपकरणों को भी अनुमति दें” पर भी निशान लगाएँ — इसके बिना मिरर सिर्फ़ इसी कंप्यूटर पर जवाब देता है — और “लागू करें” दबाएँ। एक लिंक और QR कोड दिखाई देते हैं: कोड स्कैन करें, या उसी नेटवर्क के किसी ब्राउज़र में लिंक खोलें।","docs.mirror.p2":"मिरर उसी इंजन का पालन करता है, इसलिए हर डिवाइस उसी शब्द पर होता है जिस पर ऑपरेटर। हर डिवाइस A− और A+ से अपना पाठ आकार ख़ुद तय करता है, बिना किसी और की स्क्रीन बदले।","docs.mirror.p3":"यह पेज ख़ुद ऐप परोसता है, सीधे आपके डिवाइसों तक — कभी इस वेबसाइट के ज़रिए नहीं, जिसे ब्राउज़र वैसे भी आपके नेटवर्क के किसी डिवाइस तक पहुँचने नहीं देता। यह केवल-पढ़ने के लिए है: कोई भी ब्राउज़र कुछ भी शुरू, बंद, आगे-पीछे या संपादित नहीं कर सकता। इसके लिंक में एक कुंजी होती है जो हर बार ऐप शुरू होने पर बदल जाती है। यह सादा HTTP है, इसलिए रास्ते में कुंजी एन्क्रिप्टेड नहीं होती: इसे भरोसेमंद नेटवर्क पर इस्तेमाल करें, सार्वजनिक वाई-फ़ाई पर नहीं।","docs.mirror.p4":"अगर कोई डिवाइस जुड़ नहीं पा रहा: दोनों स्विच जाँचें; पक्का करें कि वह उसी नेटवर्क पर है, मोबाइल डेटा पर या ऐसे गेस्ट नेटवर्क पर नहीं जो डिवाइसों को अलग रखता है; जब आपका सिस्टम पूछे, तो निजी नेटवर्क के लिए ऐप को अपने फ़ायरवॉल से गुज़रने दें; और अगर सेटिंग्स कहे कि मिरर शुरू नहीं हो सका, तो पोर्ट बदलें और फिर से “लागू करें” दबाएँ।","docs.readAloud.p1":"अपने सिस्टम की अपनी आवाज़ों में स्क्रिप्ट सुनने के लिए “प्रति-OS वाक् संश्लेषण से ज़ोर से पढ़ें” पर सही का निशान लगाएँ: Windows OneCore या SAPI, macOS AVSpeechSynthesis, या Linux पर Speech Dispatcher या espeak-ng। ऐप के साथ कोई आवाज़ नहीं आती।","docs.readAloud.p2":"ट्रांसपोर्ट, सीक बार और किसी शब्द पर क्लिक, आवाज़ को चलाते हैं, और हाइलाइट उसके साथ चलता है — जहाँ सिस्टम शब्दों की सीमाएँ बताता है वहाँ शब्द-दर-शब्द, बाक़ी जगह आपकी गति पर। ठहराव छोटी चुप्पी बन जाते हैं, और -- को कभी “डैश” पढ़कर नहीं सुनाया जाता।","docs.readAloud.p3":"ज़ोर से पढ़ना सिर्फ़ पूर्वावलोकन के लिए है: यह प्रोजेक्टर को कभी नहीं हिलाता। जब पाठ चल रहा हो या रुका हुआ हो, तब चेकबॉक्स तब तक लॉक रहता है जब तक आप “बंद करें” न दबाएँ। जाँच लें कि जिस कंप्यूटर से आप प्रस्तुति देंगे, उस पर यह बोलता है, ख़ासकर Linux पर।","docs.autocomplete.p1":"लिखते समय शब्द का बाक़ी हिस्सा कर्सर के आगे धुँधला दिखाई देता है; शब्द पूरा करके स्पेस दबाएँ, और यह पूरा आम वाक्यांश सुझा सकता है। Tab स्वीकार करता है, Esc हटा देता है, और टाइप करते जाने पर सुझाव अनदेखा हो जाता है।","docs.autocomplete.p2":"18 में से हर भाषा की अपनी शब्द और वाक्यांश सूचियाँ हैं — कुल 463,985 शब्द और 344,891 वाक्यांश — ऐप के भीतर, और सिर्फ़ वही भाषा लोड होती है जिसमें आप लिखते हैं। सेटिंग्स → संपादक में इसे चालू या बंद करें और इसकी भाषा चुनें, जो ऐप की भाषा से अलग हो सकती है।","docs.autocomplete.p3":"ये सूचियाँ Tatoeba वाक्य-संग्रह (CC BY 2.0 FR) से बनी हैं, जिसका श्रेय ऐप के साथ आने वाली NOTICE फ़ाइल में दिया गया है। यह एक शब्दकोश-खोज है — तुरंत, अनुमान लगाने योग्य और ऑफ़लाइन, बिना किसी मॉडल के।","docs.dictation.p1":"सेटिंग्स → आवाज़ खोलें, “बोलकर अपनी स्क्रिप्ट लिखें” पर सही का निशान लगाएँ और “लागू करें” दबाएँ। स्क्रिप्ट के ऊपर एक गोल रिकॉर्ड बटन दिखाई देता है: उसे दबाएँ और बोलें, और आप जो कहते हैं वह वहीं लिखा जाता है जहाँ आपका कर्सर है। रोकने के लिए उसे फिर से दबाएँ; माइक्रोफ़ोन सिर्फ़ इन दोनों के बीच खुला रहता है।","docs.dictation.p2":"बोलकर लिखा गया पाठ साधारण स्क्रिप्ट पाठ ही है, और Ctrl+Z आपकी कही एक बात वापस लेता है, पूरा सत्र नहीं। विराम-चिह्न और नाम ठीक करने के लिए तैयार रहें: यह मसौदे तक पहुँचने का तेज़ रास्ता है, तैयार स्क्रिप्ट नहीं।","docs.dictation.p3":"डिक्टेशन सिर्फ़ अंग्रेज़ी समझता है। यह Vosk का उपयोग करता है, जो एक ओपन-सोर्स वाक्-पहचानकर्ता है, एक छोटे अंग्रेज़ी स्पीच मॉडल के साथ — लगभग 40 MB का प्रशिक्षित न्यूरल नेटवर्क — जो ऐप के भीतर ही आता है। यह आपके कंप्यूटर पर चलता है, बिना कनेक्शन के काम करता है, कुछ भी अपलोड या डाउनलोड नहीं करता, और आपको दिखने वाले पाठ के सिवा कुछ नहीं सहेजता। जब तक आप इसे चालू न करें, यह बंद रहता है। अगर स्क्रिप्ट आपके नेटवर्क पर मिरर हो रही है, तो बोले गए शब्द लिखे जाते ही उन डिवाइसों तक पहुँच जाते हैं, टाइपिंग की तरह।","docs.settings.p1":"सेटिंग्स → दिखावट में टाइपफ़ेस, मोटाई और पाठ का रंग, किनारों के मार्जिन, पंक्ति अंतराल और पठन रेखा की जगह तय करें; फ़ॉन्ट आकार “पठन” में है। ये पूर्वावलोकन, प्रोजेक्टर और नेटवर्क मिरर पर एक साथ लागू होते हैं।","docs.settings.p2":"सेटिंग्स एक मसौदे पर काम करती हैं: जब तक आप “लागू करें” न दबाएँ, कुछ नहीं बदलता, और “रद्द करें” वही लौटा देता है जो पहले था। 18 भाषाओं में से एक चुनें, या “मेरे सिस्टम जैसी”। थीम “गहरा”, “हल्का” या “मेरे सिस्टम जैसी” होती है; आप जो भी चुनें, पठन सतह उच्च कंट्रास्ट वाली ही रहती है।","docs.settings.p3":"सेटिंग्स → सामान्य में “सिस्टम ट्रे में छोटा करें” चालू होने पर, छोटा करने से ऐप टास्कबार के बजाय ट्रे में चला जाता है। “परिचय दोबारा दिखाएँ”, जो “सामान्य” में ही है, स्वागत परिचय को फिर से चलाता है।","docs.access.p1":"ऐप के पहली बार खुलने पर, लाइसेंस के बाद, चार चरणों का परिचय संपादक और उसके ठहराव-चिह्न, गति के नियंत्रण और प्रोजेक्टर दिखाता है। “छोड़ें”, Esc या उसके बाहर क्लिक करने से यह हमेशा के लिए बंद हो जाता है; सेटिंग्स → सामान्य → परिचय दोबारा दिखाएँ इसे वापस लाता है।","docs.access.p2":"कीबोर्ड से किसी नियंत्रण तक पहुँचने पर वह फ़ोकस रिंग दिखाता है। Tab खुले डायलॉग के भीतर ही रहता है, Esc उसे बंद करता है, और फ़ोकस उसी बटन पर लौटता है जिसने उसे खोला था। सीक बार एक असली स्लाइडर है: तीर कुंजियाँ एक अक्षर आगे-पीछे करती हैं, Page Up और Page Down एक स्क्रीन भर, और Home और End दोनों सिरों पर ले जाती हैं।","docs.access.p3":"अगर आपका सिस्टम कम गति माँगता है, तो एनिमेशन और धुंधलापन हटा दिए जाते हैं, जबकि स्क्रिप्ट ख़ुद स्क्रॉल होती रहती है; कम पारदर्शिता होने पर डायलॉग पृष्ठभूमि को धुंधला करने के बजाय गहरा कर देते हैं।","docs.problems.p1":"जब कुछ ऐसा गड़बड़ होता है जिसके बारे में ऐप आपको बता सकता है, तो उसके संदेश के बगल में “रिपोर्ट करें” बटन होता है। क्रैश के बाद, अगली बार खुलने पर “रिपोर्ट करें” और “खारिज करें” वाली एक पट्टी दिखती है।","docs.problems.p2":"“रिपोर्ट करें” आपके ब्राउज़र में Freally Teleprompt का रिपोर्ट पेज खोलता है, जिसमें तकनीकी विवरण पहले से भरे होते हैं: आप उन्हें पढ़ सकते हैं, पर बदल नहीं सकते। लिखें कि आप क्या कर रहे थे और, चाहें तो, एक ईमेल पता। जब तक आप उस पेज पर “भेजें” न दबाएँ, कुछ नहीं भेजा जाता, और पृष्ठभूमि में कभी कुछ नहीं भेजा जाता।","docs.problems.p3":"हर बार शुरू होने पर एक बार, ऐप GitHub से पूछता है कि क्या कोई नया संस्करण है। अगर है, तो आप उसका संस्करण नंबर और रिलीज़ नोट्स देखते हैं और हाँ या नहीं चुनते हैं; इंस्टॉल होने से पहले अपडेट को ऐप के भीतर की साइनिंग कुंजी से जाँचा जाता है। जब आप ऑफ़लाइन हों या पहले से नवीनतम संस्करण पर हों, तो यह कुछ नहीं कहता। टूलबार पर “अपडेट जाँचें” किसी भी समय फिर से पूछता है।","docs.privacy.p1":"न कोई खाता, न टेलीमेट्री। आपकी स्क्रिप्ट आपके कंप्यूटर पर .ftscript फ़ाइलें हैं, वहीं जहाँ आप उन्हें सहेजते हैं, और ऐप के लेखक को वे कभी नहीं मिलतीं।","docs.privacy.p2":"ऐप इंटरनेट से जो इकलौता अनुरोध करता है, वह अपडेट की जाँच है, जो न कोई स्क्रिप्ट भेजती है, न सेटिंग्स, न कोई पहचान-सूचक। समस्या की रिपोर्ट सिर्फ़ आपके ब्राउज़र के रिपोर्ट पेज से जाती है, जब आप “भेजें” दबाते हैं। प्रोजेक्टर और नेटवर्क मिरर आपके अपने डिस्प्ले और आपके अपने नेटवर्क पर ही रहते हैं।","docs.privacy.p3":"मशीन लर्निंग का उपयोग सिर्फ़ एक जगह होता है: डिक्टेशन का स्पीच मॉडल, जो आपके कंप्यूटर पर चलता है और जब तक आप चालू न करें, बंद रहता है। ऑटोकम्प्लीट एक शब्दकोश-खोज है, ज़ोर से पढ़ना आपके सिस्टम की अपनी आवाज़ों का उपयोग करता है, और आप जो टाइप करते हैं या कहते हैं वह किसी AI सेवा को नहीं भेजा जाता।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.price":"Freally Teleprompt आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.ladder.planned":"नियोजित","kit.ladder.goal":"लक्ष्य","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">आठ ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally Teleprompt में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v1.5.0","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.planned":"अभी बनना बाकी है","kit.states.goal":"वह संस्करण जिस तक यह रास्ता जाता है","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally Teleprompt में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.changelog.unreleased":"अप्रकाशित","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">अप्रकाशित</span></span>","changelog.c205924de0fe":"दस्तावेज़ीकरण","changelog.3ba1bf71dedb":"<strong>वेबसाइट नए सिरे से बनाई गई है</strong>, Freally परिवार के डिज़ाइन में, और वह ऐप की सभी 18 भाषाएँ बोलती है — यह बदलाव लॉग भी। इस पर कोई डाउनलोड नहीं है।","changelog.184abbf86c34":"<span class=\"release__meta\"><span class=\"release__ver\">v1.5.0</span></span><span class=\"release__title\">5 अगस्त 2026</span>","changelog.4a6a7a1ffbc7":"कमरे में मौजूद कोई भी चीज़ प्रॉम्प्टर चला सकती है।","changelog.6b02e0d363a4":"जोड़ा गया","changelog.21717d79a98c":"<strong>फ़ुट पेडल और प्रेज़ेंटर रिमोट।</strong> शूट पर प्रॉम्प्टर असल में पेडल से ही चलाया जाता है — आपके हाथ कैमरे पर होते हैं, कीबोर्ड पर नहीं। <strong>शॉर्टकट</strong> खोलें, जिस बंधन को बदलना है उसे दबाएँ, फिर पेडल दबाएँ: वह जो भी भेजता है वही सहेज लिया जाता है, बिना किसी ड्राइवर और बिना किसी सेटअप के। ज़्यादातर पेडल और रिमोट <code>F13</code>–<code>F24</code> भेजते हैं, ठीक इसलिए कि इनका और कोई उपयोग नहीं करता, और अब ये भी किसी दूसरी कुंजी की तरह बाँधी जा सकती हैं।","changelog.87aef9902031":"<strong>ऐसी कुंजियाँ जो तब भी काम करती हैं जब Freally Teleprompt सामने न हो।</strong> ऑपरेटर आमतौर पर किसी कैमरा ऐप, DAW या OBS में होता है, इसलिए हर ट्रांसपोर्ट कमांड को एक दूसरा बंधन दिया जा सकता है, जिसे ऑपरेटिंग सिस्टम आप जहाँ भी हों वहाँ पहुँचा देता है।","changelog.d6a3a80ffa2c":"<strong>आपके कहे बिना कुछ भी नहीं लिया जाता।</strong> शुरुआत में कोई भी सिस्टम-व्यापी कुंजी पंजीकृत नहीं होती — बिना पूछे किसी कुंजी को बाक़ी हर प्रोग्राम से छीन लेना ऐसा काम नहीं है जो कोई ऐप पहली बार चलने पर करे।","changelog.e134c7c903f4":"<strong>अस्वीकार की गई कुंजी यह बताती है।</strong> अगर वह संयोजन पहले से किसी दूसरे प्रोग्राम के पास है, तो पंक्ति आपको कारण सहित बता देती है। Wayland में, जो ऐप्लिकेशन को सिस्टम-व्यापी कुंजियाँ लेने ही नहीं देता, डायलॉग यह भी बताता है, बजाय ऐसा बंधन दिखाने के जो चुपचाप कुछ नहीं करता।","changelog.dfedb41c2cf4":"<strong>हर कमांड का खोजने योग्य नक्शा, जिसके बंधन बदले जा सकते हैं</strong>, टकरावों की पहचान के साथ — किसी कमांड को उसके नाम से खोजें, या ख़ुद कुंजी से, जब आप जानना चाहें कि <code>F13</code> इस समय क्या कर रहा है। किसी बंधन को मिटाएँ, या साथ आए डिफ़ॉल्ट वापस लाएँ, कभी भी।","changelog.b74f3602a847":"<strong>एक ही तालिका सब कुछ चलाती है।</strong> पूर्वावलोकन, प्रोजेक्टर विंडो, पेडल और सिस्टम-व्यापी हॉटकी सभी एक ही बंधन पढ़ते हैं, इसलिए कोई कुंजी बदलने पर वह हर जगह एक साथ बदल जाती है — प्रस्तुतकर्ता का प्रोजेक्टर भी, जो बंधन बदलने पर बिना दोबारा खोले उसे अपना लेता है।","changelog.3573af4808a8":"स्क्रिप्ट लिखते समय स्पेस बार, तीर कुंजियाँ और Home अब भी सामान्य रूप से टाइप करती हैं: अकेली कुंजी अपना कमांड तभी चलाती है जब आप संपादक में न हों।","changelog.1246fc93bca0":"ठीक किया गया","changelog.07ff9553768e":"<strong>दस्तावेज़ आयात करना (1.4.0 का <code>Import</code>), जहाँ मूल बात यह है: जो कन्वर्टर चुपचाप आपकी स्क्रिप्ट बदल दे, वह उससे बुरा है जो उसे अस्वीकार कर दे।</strong>","changelog.0ec8d88f6052":"<strong>PDF अब यह दावा नहीं करता कि उसे पता है कि क्या छूट गया।</strong> बाक़ी हर प्रारूप एक दस्तावेज़ मॉडल पर चलते हुए पढ़ा जाता है, इसलिए “और कुछ नहीं छूटा” ऐसी बात है जिसे आयातक सचमुच जाँच सकता है। PDF में ऐसी कोई संरचना नहीं होती — वहाँ ख़ाली सूची का मतलब है <em>हम बता नहीं सके</em> — और कुछ और कहना उसी प्रारूप पर झूठा भरोसा दिलाना था जिसमें आकृतियाँ और पाद-टिप्पण होने की संभावना सबसे ज़्यादा होती है।","changelog.7ea47b0b9557":"<strong>Word का टेक्स्ट बॉक्स अब गुम तस्वीर के रूप में नहीं बताया जाता।</strong> उसका पाठ शुरू से ही आयात हो रहा था, और साथ ही उसे छोड़ी गई तस्वीर के रूप में भी गिना जा रहा था। अब वह अपना अलग अनुच्छेद बनता है, बजाय उस पंक्ति में घुसा दिए जाने के जिससे वह संयोग से जुड़ा था — “हम ऑन कैमरा वाइड शॉट पर कट करते हैं” वह नहीं है जो दस्तावेज़ कहता है।","changelog.9962e4f893ac":"<strong>तस्वीरें और रनिंग हेड एक ही बार गिने जाते हैं, और सिर्फ़ वहीं जहाँ उनका उपयोग हुआ हो।</strong> एक ही फ़ोटो को दो बताया जाता था, और Word हर दस्तावेज़ में तीन शीर्षलेख और तीन पादलेख लिखता है, चाहे उनका उपयोग हो या न हो — इसलिए एक रनिंग हेड को छह बताया जाता था। “छोड़ी गई तस्वीरें: 2” पढ़ने वाला ऑपरेटर एक ऐसी दूसरी तस्वीर ढूँढने लगता है जो कभी थी ही नहीं।","changelog.07aaaf2b256f":"<strong>जिन अक्षरों को Word एलिमेंट के रूप में सहेजता है, वे अब चुपचाप नहीं खोते</strong> — <code>co‑operate</code> आयात होकर <code>cooperate</code> बन जाता था। सिंबल-फ़ॉन्ट का ग्लिफ़ अब अनुमान लगाने के बजाय छोड़ी गई चीज़ के रूप में गिना जाता है, क्योंकि उसका कोड पॉइंट किसी फ़ॉन्ट में एक सूचकांक है, कोई अक्षर नहीं।","changelog.c15eb04425e7":"<strong>जो फ़ाइल यूनिकोड होने का दावा करती है पर है नहीं, अब उसकी सूचना दी जाती है।</strong> कुछ टूल UTF-8 के तीन मार्कर बाइट लगा देते हैं और फिर भी पश्चिमी यूरोपीय पाठ लिखते हैं; ऐसी फ़ाइल आयात होने पर एक्सेंट वाला हर अक्षर <code>�</code> से बदल जाता था, <strong>और</strong> रिपोर्ट कहती थी कि कुछ भी नहीं छूटा — ठीक वही विफलता जिसे रोकने के लिए एन्कोडिंग वाली सूचना बनी है, उस इकलौते रास्ते से पहुँची जो जाँच को छोड़ देता था।","changelog.3e2d09e4e749":"<strong>डैश को सामान्य करने से अब फिर कभी कोई ठहराव नहीं बन सकता।</strong> दो डैश के बीच बैठा शून्य-चौड़ाई वाला स्पेस या भटका हुआ मार्कर बाइट — जो वेब और PDF से आए पाठ में अक्सर होता है — उस क्रम को दो हिस्सों में बाँट देता था, और <code>a —​— b</code> एक ऐसे <code> -- </code> ठहराव के रूप में आयात होता था जिसे किसी ने नहीं लिखा। RTF भी एक अलग रास्ते से उसी ग़लत मोड़ पर पहुँचा था।","changelog.cdc8dc821ad8":"<strong>RTF: अंतर्निहित तस्वीर या वस्तु अब स्क्रिप्ट में नहीं रिसती।</strong> बाइनरी डेटा को ऐसे पढ़ा जा रहा था मानो वह पाठ हो, इसलिए उसके भीतर का पहला <code>}</code> बाइट — जो किसी भी बाइनरी डेटा में लगभग हर 256 बाइट में एक बार आता है — छोड़ने की प्रक्रिया को समय से पहले ख़त्म कर देता था और बाक़ी हिस्सा स्क्रिप्ट में डाल देता था।","changelog.c62855d7561c":"<strong>RTF: इमोजी और दूसरे एस्ट्रल अक्षर अब बचे रहते हैं।</strong> वे एक सरोगेट जोड़ी के दो हिस्सों के रूप में आते हैं, और कोई भी हिस्सा अपने आप में अक्षर नहीं है, इसलिए दोनों हटा दिए जा रहे थे। नॉन-ब्रेकिंग स्पेस और हाइफ़न भी अब अपने असली रूप में आयात होते हैं।","changelog.456985ca40d6":"<strong>दस्तावेज़ पढ़े जाते समय ऐप अब नहीं अटकता।</strong> कोई बड़ा PDF विंडो को नब्बे सेकंड तक रोके रख सकता था।","changelog.5ff5476a8e49":"<strong>धीमा आयात अब ग़लत डायलॉग में नहीं पहुँच सकता।</strong> डायलॉग बंद करें, फिर खोलें, कोई दूसरी फ़ाइल चुनें — और पहले दस्तावेज़ का नतीजा आ पहुँचता था और रिपोर्ट, पूर्वावलोकन <em>और</em> नाम बदल देता था, इसलिए आयात करें दबाने पर ऐसी स्क्रिप्ट सहेजी जाती थी जिसे आपने चुना ही नहीं था, ऐसे नाम से जो आपके देखते-देखते बदल गया था।","changelog.ca076d4847ef":"<strong>विफल सहेजना अब पीछे कोई अधूरी फ़ाइल नहीं छोड़ता।</strong> अगर लिखना विफल हो जाता — केवल-पढ़ने वाला फ़ोल्डर, भरी हुई डिस्क, कोई फ़ाइल जिसे सिंक क्लाइंट ने लॉक कर रखा हो — तो आपके चुने नाम से एक ख़ाली स्क्रिप्ट लाइब्रेरी में रह जाती थी, और दोबारा आयात करने पर “इस नाम की स्क्रिप्ट पहले से मौजूद है” त्रुटि आती थी। उसे आपको हाथ से हटाना पड़ता था। पिछली स्थिति पर लौटने की प्रक्रिया असली त्रुटि को कभी नहीं छिपाती।","changelog.81f5afe81f74":"<strong>खोजें और बदलें (1.4.0 का <code>Find</code>)</strong>","changelog.df4d2a98d916":"<strong>बदलें अब स्क्रिप्ट को वैसे ही संपादित करता है जैसी वह अभी है, न कि जैसी वह एक पल पहले थी।</strong> बदलें और सभी बदलें, दोनों की गणना एक ऐसी प्रति पर होती थी जो संपादक से एक राउंड-ट्रिप पीछे रहती है — इसलिए उसी अंतराल में आया कोई बोला गया वाक्य ऊपर से लिखकर मिट जाता था, और किसी मिलान की स्थिति ग़लत अक्षरों की ओर इशारा कर सकती थी।","changelog.0cc222aab642":"<strong>ऐसे पाठ से बदलना, जिसमें खोजा गया पाठ ही शामिल हो, अब आगे बढ़ता है।</strong> “कर” को “करना” से बदलने पर तीन बार दबाने में एक ही शब्द “करनाना” बन जाता था, जबकि बाक़ी दो अछूते रहते थे, और काउंटर पूरे समय “3 में से 1” दिखाता था।","changelog.fa5b9ccac936":"<strong>रिहर्सल रिपोर्ट (1.3.0 का रिहर्सल मोड)</strong>","changelog.e72cfed29d53":"<strong>एक भटका हुआ शीर्षक अब रिपोर्ट को नहीं समेट देता।</strong> बारह अनुच्छेदों वाली स्क्रिप्ट, जिसमें Markdown आयात से आया एक अकेला <code># Title</code> हो — या शॉट-लिस्ट की एक पंक्ति <code>#3 CAMERA B</code> — बारह पंक्तियों से घटकर दो रह जाती थी, और वे अनुच्छेद-वार समय खो जाते थे जिनके लिए रिपोर्ट बनी है। एक चिह्न स्क्रिप्ट को नाम देता है; वह उसे खंडों में नहीं बाँटता।","changelog.cc295a583a87":"<span class=\"release__meta\"><span class=\"release__ver\">v1.4.0</span></span><span class=\"release__title\">4 अगस्त 2026</span>","changelog.4f39388d525b":"स्क्रिप्ट को अंदर लाना, और उसमें अपना रास्ता ढूँढना।","changelog.2bfa1e157a29":"<strong>वह फ़ाइल खोलें जो आपको भेजी गई थी।</strong> अब तक पाठ प्रॉम्प्टर तक सिर्फ़ टाइप करके या पेस्ट करके पहुँचता था, जबकि कोई भी स्क्रिप्ट इस तरह नहीं आती। टूलबार का <strong>आयात</strong> बटन <strong>Word (<code>.docx</code>), RTF, PDF, सादा पाठ और Markdown</strong> पढ़ता है और उन्हें साफ़ प्रॉम्प्टर पाठ में बदल देता है: अनुच्छेद बने रहते हैं; बोल्ड, फ़ॉन्ट और रंग सादे कर दिए जाते हैं; घुमावदार उद्धरण-चिह्न, एम डैश और एलिप्सिस सामान्य कर दिए जाते हैं; और ग़लत एन्कोडिंग में सहेजी गई फ़ाइल को टूटे-फूटे अक्षरों के रूप में दिखाने के बजाय सही पढ़ा जाता है और इसकी सूचना दी जाती है।","changelog.514edf636361":"<strong>जो चीज़ें यह नहीं ला सका, वह आपको बताता है</strong> — तस्वीरें, पाद-टिप्पण, टिप्पणियाँ, शीर्षलेख और पादलेख, लिंक पते, अंतर्निहित वस्तुएँ, हर एक की गिनती के साथ। जो कन्वर्टर इन्हें चुपचाप गिरा दे, उसके बारे में आपको शूट पर ही पता चलता है।","changelog.b9c0ccd7f34c":"<strong>आपके कहे बिना कुछ भी सहेजा नहीं जाता।</strong> आप पाठ और रिपोर्ट देखते हैं, स्क्रिप्ट को नाम देते हैं, और तभी आपकी लाइब्रेरी में कोई फ़ाइल आती है — और कोई आयात पहले से मौजूद स्क्रिप्ट को कभी ओवरराइट नहीं करेगा।","changelog.d2b1a7638b2a":"डैश को सामान्य करने से कभी कोई ठहराव नहीं बन सकता: छपाई वाला <code>—</code> एक साधारण हाइफ़न बन जाता है, और लगातार दो ऐसे डैश इस ऐप के <code> -- </code> ठहराव टोकन में नहीं बदलते। असली ठहरावों के साथ आपकी लिखी <code>.txt</code> फ़ाइल उन्हें बनाए रखती है।","changelog.90b7cc8211d3":"<strong>खंड-चिह्न, जंप सूची के साथ।</strong> <code>#</code> से शुरू होने वाली हर पंक्ति — <code># Verse 2</code>, <code># Q&amp;A</code> — एक पहचान-चिह्न है, और वैसे ही हर वह पंक्ति भी जो आपके छोड़े जाने वाले शब्दों में से कोई एक हो (<code>[Chorus]</code>, <code>Bridge</code>)। वे सीक बार के बगल में एक जंप सूची में दिखते हैं, ख़ुद बार पर रेखाओं के रूप में अंकित होते हैं, और <strong>अगला / पिछला</strong> उन पर एक-एक करके चलते हैं। कुछ भी कॉन्फ़िगर नहीं करना है, और आयात की गई Markdown स्क्रिप्ट अपनी सूची पहले से बनी हुई लेकर आती है।","changelog.697fb23f904c":"पिछला पहले उस खंड की शुरुआत पर जाता है जिसमें आप हैं, फिर उससे पीछे — जैसे पिछले ट्रैक वाला बटन करता है।","changelog.ce1cd4f6f1f3":"<strong>खोजें और बदलें</strong> (<code>Ctrl+F</code>), खुली स्क्रिप्ट तक सीमित: मिलानों की लाइव गिनती, अक्षर-आकार का मिलान, केवल पूरे शब्द, बदलें और सभी बदलें। मौजूदा मिलान संपादक में रोशन होता है, पर आपकी टाइपिंग खोज बॉक्स से बाहर नहीं जाती, और सभी बदलें को Ctrl+Z के <strong>एक ही</strong> दबाव से पलटा जा सकता है।","changelog.164dc61c0ad5":"<strong>स्क्रिप्ट के आँकड़े</strong>, पढ़ने के समय के अनुमान के नीचे: शब्दों की गिनती, अक्षरों की गिनती, और एक चेतावनी जब कोई पंक्ति इतनी लंबी हो कि रैप होकर पूरा अनुच्छेद बन जाए। गिनती उसी की होती है जो असल में <strong>प्रस्तुत किया जाता</strong> है — छोड़े गए लेबल और ठहराव टोकन शामिल नहीं होते, इसलिए गिनती बगल में दिखी अवधि से मेल खाती है।","changelog.2a6141e43be0":"बदला गया","changelog.24b7a7366360":"रिहर्सल रिपोर्ट के खंड अब छोड़े जाने वाले लेबलों के साथ-साथ चिह्नों पर भी बँटते हैं, इसलिए <code>#</code> शीर्षकों से लिखी स्क्रिप्ट बिना कोई कीवर्ड कॉन्फ़िगर किए खंड-दर-खंड रिहर्स होती है। खंड का नाम उसकी सजावट के बिना आता है: <code>[Verse 1]</code> रिपोर्ट में <em>Verse 1</em> के रूप में दिखता है।","changelog.8f6fb4eb7f42":"सुरक्षा","changelog.9dc7532525e8":"हर दस्तावेज़ पार्सर एक <strong>अलग प्रोसेस</strong> में चलता है। पाँच में से तीन प्रारूप थर्ड-पार्टी क्रेट पढ़ते हैं, ऐसी फ़ाइल पर जो ऐप ने नहीं लिखी, और रिलीज़ बिल्ड पैनिक होने पर बंद हो जाते हैं — इसलिए वरना कोई ख़राब PDF पढ़ते-पढ़ते प्रॉम्प्टर को गिरा सकता था। इससे काम को एक समय-सीमा भी मिलती है और बेक़ाबू पार्सर की मेमोरी ऐप से बाहर रहती है।","changelog.bbb6d70966f6":"आयात की अस्थायी फ़ाइल एक नई बनी डायरेक्टरी में बनती है जिसका नाम अनुमान से परे होता है, और Unix पर ऐसी डायरेक्टरी में जिसमें सिर्फ़ उसका मालिक प्रवेश कर सकता है।","changelog.0fdcda0b6a1e":"<span class=\"release__meta\"><span class=\"release__ver\">v1.3.0</span></span><span class=\"release__title\">3 अगस्त 2026</span>","changelog.4245679cbf6a":"समय पर पढ़ना — और वे शब्द जिन्हें गिना नहीं जाना चाहिए।","changelog.3a8bc8eb9047":"<strong>टेम्पो थपथपाएँ, और ऐप आपका टेम्पो सीख लेता है।</strong> BPM को हमेशा एक ही संख्या से पढ़ने की गति में बदला गया है: एक मात्रा में आप कितने अक्षर पढ़ लेते हैं। पहले यह एक अनुमान था — बैलेड गायक और रैपर के लिए एक जैसा अनुमान, जबकि दोनों में दस गुना का अंतर होता है। <strong>सेटिंग्स → समय-निर्धारण</strong> अब आपको उसी टेम्पो पर थपथपाने देता है जिस पर आप सचमुच प्रस्तुति देते हैं, और इस संख्या को मान लेने के बजाय आपकी अपनी पढ़ने की गति से मापता है।","changelog.b94cb35d22f5":"जो कैलिब्रेशन संगीत की रेंज के किसी हिस्से को इंजन की पहुँच से बाहर कर दे, वह <strong>BPM बॉक्स में दी जाने वाली रेंज को छोटा कर देता है</strong>, बजाय आपको ऐसी संख्याएँ दिखाने के जिन्हें वह चुपचाप पीछे से बदल देता।","changelog.4b0c4241773f":"<strong>मेट्रोनोम।</strong> स्क्रिप्ट स्क्रॉल होते समय हर मात्रा पर एक वैकल्पिक क्लिक, ताल की पहली मात्रा पर ज़ोर के साथ, और शुरुआती काउंटडाउन ही उसकी आरंभिक गिनती बन जाता है। ऐप इसकी ध्वनि ख़ुद बनाता है — इंस्टॉलर में कोई ऑडियो फ़ाइल नहीं है और कुछ भी डाउनलोड नहीं होता। हर क्लिक का समय उसकी मात्रा की क्रम-संख्या से ऑडियो घड़ी के हिसाब से तय होता है, इसलिए वह स्क्रॉल से भटकता नहीं: ऐप के सबसे तेज़ टेम्पो पर दस मिनट के पाठ में मापने पर भी आख़िरी क्लिक ठीक समय पर रहता है।","changelog.a0c53f6c5b09":"<strong>ताल और मात्रा काउंटर</strong>, पठन सतह के बगल में, और <strong>सीक बार पर अंकित ताल-रेखाएँ</strong> — ताकि “सोलह ताल” ऐसी चीज़ हो जिसे आप देख सकें, न कि मन में गिनें। दोनों तभी दिखते हैं जब आप किसी टेम्पो पर काम कर रहे हों।","changelog.84aa1a93cd53":"<strong>रिहर्सल मोड, समय की रिपोर्ट के साथ।</strong> स्क्रिप्ट पूरी पढ़ें और ऐप आपको खंड-दर-खंड बताता है कि उसमें कितना समय लगना चाहिए था और कितना लगा, और वह गति सुझाता है जिस पर आपने उसे सचमुच पढ़ा। यह <strong>सिर्फ़ समय दर्ज करता है, और कुछ नहीं</strong> — इसमें न कोई माइक्रोफ़ोन है, न कोई ऑडियो पथ, और यह बात यहाँ सिर्फ़ वादा नहीं, एक टेस्ट से साबित की जाती है।","changelog.3bcd3e611ff3":"रिहर्सल के दौरान <strong>एक शांत गति-चेतावनी</strong>, जब पाठ अपनी योजना से कुछ सेकंड से ज़्यादा खिसक जाए — ताकि लंबा खिंचता खंड अंत के बाद नहीं, पहले ही दिख जाए।","changelog.440434188c4b":"<strong>वे शब्द जिन्हें आप पढ़ते हैं पर प्रस्तुत नहीं करते।</strong> <strong>सेटिंग्स → समय-निर्धारण</strong> में “Chorus”, “Verse” या “Bridge” डालें, और जो पंक्ति सिर्फ़ इनमें से किसी एक की हो — <code>Chorus</code>, <code>[Verse 1]</code>, <code>## Bridge</code> — <strong>उसमें कोई समय नहीं लगता</strong>, इसलिए आपके बोल उसी ताल पर पड़ते हैं जिसके लिए आपने उन्हें लिखा था। असली पंक्ति के भीतर वही शब्द सिर्फ़ ख़ुद को छोड़ता है, इसलिए “अब वापस Chorus पर” का समय बना रहता है। वे स्क्रीन पर धुँधले दिखते रहते हैं, और ज़ोर से पढ़ना उन्हें कभी नहीं बोलता।","changelog.c06854290d9c":"<span class=\"release__meta\"><span class=\"release__ver\">v1.2.0</span></span><span class=\"release__title\">2 अगस्त 2026</span>","changelog.b16edf96208e":"रिकॉर्ड बटन, और बोलने के बाद शब्दों के साथ क्या होता है।","changelog.e03e88337492":"<strong>रिकॉर्ड बटन एक बटन है, वाक्य नहीं।</strong> अब यह एक गोला है जिसके भीतर एक चिह्न है — रिकॉर्ड करने के लिए <strong>●</strong>, रोकने के लिए <strong>■</strong> — और निर्देश उसके भीतर नहीं, बगल में है, इसलिए इस्तेमाल करते समय नियंत्रण की चौड़ाई बदलना बंद हो जाता है। इसका रंग इसकी स्थिति के साथ-साथ आपके पॉइंटर के हिसाब से भी बदलता है: रिकॉर्ड बटन पर होवर करें तो वह हरा हो जाता है, और रिकॉर्डिंग के दौरान उस पर होवर करने से वह लाल हो जाता है। पॉइंटर हटाते ही वह पहले जैसा हो जाता है, और वह जो करेगा उसमें कोई बदलाव नहीं होता।","changelog.f7a0e2da64e7":"<strong>बोलकर लिखे गए शब्द अब संपादक से होकर जाते हैं</strong>, जहाँ से उन्हें हमेशा जाना चाहिए था। इससे तीन बातें निकलती हैं, और इनमें से हर एक पहले एक असली ख़राबी थी:","changelog.8e6453161785":"<strong>पूर्ववत करना आपकी कही एक बात वापस लेता है</strong>, पूरा सत्र नहीं। पहले Ctrl+Z एक ही कदम में आपकी बोलकर लिखी हर चीज़ को पार कर जाता था।","changelog.c4b4bb124914":"<strong>रिकॉर्डिंग के दौरान आपका टाइप किया पाठ बना रहता है।</strong> पहले आपकी कही अगली बात उसे ओवरराइट कर देती थी।","changelog.f9033b43c6e5":"<strong>शब्द वहीं पहुँचते हैं जहाँ आपका कर्सर है</strong>, हमेशा स्क्रिप्ट के अंत में नहीं।","changelog.d766eb074a43":"स्पीच मॉडल का <strong>फ़ोल्डर</strong> मौजूद होने पर डिक्टेशन ख़ुद को तैयार बता देता था, भले ही उसके अंदर का मॉडल ग़ायब हो या आधा ही कॉपी हुआ हो — जिससे स्क्रीन पर ऐसा रिकॉर्ड बटन आ जाता था जो दबाने पर सिर्फ़ विफल ही हो सकता था। अब यह उस एक फ़ाइल की जाँच करता है जिसके बिना पहचानकर्ता शुरू नहीं हो सकता।","changelog.4b11a58f4f52":"<strong>बिना ड्राइव-अक्षर वाले वॉल्यूम</strong> (किसी फ़ोल्डर में माउंट की गई ड्राइव) पर इंस्टॉल होने पर, पहचानकर्ता को दिया गया मॉडल पथ ऐसे पथ में बदल जाता था जो किसी भी चीज़ की ओर इशारा नहीं करता था। अब वह मॉडल की ओर इशारा करता है। ऐसे सेटअप पर पहचानकर्ता उसे लोड कर पाता है या नहीं, यह परखा नहीं गया है — लेकिन वहाँ विफल होने पर वह बताता है कि कौन-सा मॉडल नहीं खुल सका, बजाय चुपचाप किसी बिल्कुल दूसरी जगह देखने के।","changelog.c0965fe505ea":"कर्सर स्क्रिप्ट में <strong>बिल्कुल ऊपर</strong> होने पर डाला गया पाठ वहाँ के बजाय नीचे पहुँच सकता था। संपादक ऐसी कर्सर स्थिति नहीं पढ़ पाता था जो किसी पंक्ति के भीतर नहीं, बल्कि पूरी स्क्रिप्ट पर हो, और जवाब में पूरे पाठ की लंबाई दे देता था — इसलिए पेस्ट किया गया पाठ, या बोलकर लिखी गई पंक्ति, अंत में चली जाती थी।","changelog.15f80b1047f4":"डिक्टेशन ख़ुद को <strong>अनुपलब्ध बता सकता था, जबकि एक बिल्कुल ठीक मॉडल इंस्टॉल था</strong>: आपके डेटा फ़ोल्डर में पड़े किसी भटके हुए या आधे कॉपी हुए <code>vosk-model-en</code> को ऐप के भीतर वाले मॉडल पर तरजीह दी जाती थी, और फिर अधूरा होने के कारण अस्वीकार कर दिया जाता था। अब ऐप बेकार फ़ोल्डर को छोड़ देता है और अपने साथ आए मॉडल का उपयोग करता है।","changelog.4ecc1ea9414e":"योगदानकर्ताओं के लिए <code>npm run dev:vosk</code> — एक डेवलपमेंट रन जो सचमुच डिक्टेट कर सकता है। वरना डिक्टेशन सिर्फ़ रिलीज़ बिल्ड में होता है, जिससे उस पर काम करना मुश्किल था।","changelog.9ef45f3d9beb":"डॉक्स साइट की खोज अब <strong>डिक्टेशन</strong> ढूँढ लेती है — यह फ़ीचर 1.1.0 में आया था पर इंडेक्स में नहीं था, इसलिए उसे खोजने पर कुछ नहीं मिलता था। दूसरी ओर, ऐसे खोज-परिणाम हटा दिए गए हैं जिनका नतीजा हमेशा 404 ही होता: साझा इंडेक्स में पाँच ऐसे Freally ऐप सूचीबद्ध थे जिनकी अभी कोई साइट नहीं है, जो उसकी 109 प्रविष्टियों में से 39 थीं।","changelog.1569fac6a9e5":"<code>THIRD-PARTY.md</code> फ़ॉन्ट्स के साथ-साथ <strong>Vosk</strong> (इंजन, मॉडल और Windows MinGW रनटाइम) को भी दर्ज करता है; <code>NOTICE</code> में अब उस रनटाइम के संबंधित सोर्स कोड के संदर्भ हैं। दोनों फ़ाइलें इंस्टॉलर के भीतर आती हैं।","changelog.a02b0fb176eb":"डिक्टेशन के लिए सेटिंग्स का नोट बताता है कि <strong>LAN मिरर</strong> चालू होने पर क्या होता है: बोलकर लिखा गया पाठ लिखे जाते ही उसके दर्शकों तक पहुँच जाता है, ठीक टाइपिंग की तरह।","changelog.226b619dcadb":"<span class=\"release__meta\"><span class=\"release__ver\">v1.1.0</span></span><span class=\"release__title\">2 अगस्त 2026</span>","changelog.d3ca2e44459c":"अपनी आवाज़ के उपयोग का एक ही तरीका, और वह चालू करते ही काम करता है।","changelog.b370d746f358":"<strong>बोलकर अपनी स्क्रिप्ट लिखें</strong> (FT-33) — सेटिंग्स → आवाज़ में <strong>डिक्टेशन</strong> चालू करें, और स्क्रिप्ट के ऊपर एक रिकॉर्ड बटन दिखाई देता है। उसे दबाएँ और आप जो कहते हैं वह लिखा जाता है; रोकने के लिए उसे फिर से दबाएँ।","changelog.e02d4e39e7e3":"इसे न किसी प्रशिक्षण की ज़रूरत है, न सेटअप की: स्पीच मॉडल इंस्टॉलर के भीतर आता है, इसलिए यह चालू करते ही काम करता है। चलते समय कुछ भी डाउनलोड नहीं होता और कुछ भी कहीं नहीं भेजा जाता — पहचानकर्ता और उसका मॉडल आपकी मशीन पर हैं, और ऑफ़लाइन भी यही सच रहता है। माइक्रोफ़ोन सिर्फ़ रिकॉर्डिंग के दौरान खुला रहता है, और आपकी कही बात में से सिर्फ़ पाठ ही किसी फ़ाइल में लिखा जाता है।","changelog.4118fb4fed0e":"हटाया गया","changelog.9201332ddf55":"<strong>वॉइस कमांड हटा दिए गए हैं।</strong> इनमें से कोई भी कुछ करे, उससे पहले आपको हर कमांड — चलाएँ, रोकें, तेज़, धीमा, अगला ठहराव, शुरुआत पर लौटें — अपनी आवाज़ में रिकॉर्ड करना पड़ता था, और फिर बोलते समय एक बटन दबाए रखना पड़ता था। जब तक आपने वह रिकॉर्डिंग न की हो, बटन दबाए रखने से माइक्रोफ़ोन खुल जाता था और कुछ भी हासिल नहीं होता था, और इसे किसी ख़राबी से अलग पहचानने का कोई तरीका नहीं था। डिक्टेशन बिना कुछ प्रशिक्षित किए वही काम करता है।","changelog.8afda10a9120":"<strong>“मेरे पढ़ने का पालन करें” भी हटा दिया गया है</strong>, इसी कारण से: आवाज़ के उपयोग का एक साफ़ तरीका, एक-दूसरे पर चढ़ते तीन तरीकों से बेहतर है। इसके पीछे का संरेखण का काम अब भी एक लाइब्रेरी के रूप में मौजूद है और किसी दूसरे रूप में लौट सकता है।","changelog.119dd324728e":"इसी हिसाब से इंस्टॉलर 1.0.0 वालों से बड़े हैं — स्पीच मॉडल लगभग 40 MB का है, और अब यह साथ आता है, चाहे आप इसका उपयोग करें या न करें।","changelog.9133884e4863":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span></span><span class=\"release__title\">2 अगस्त 2026</span>","changelog.3d6b5cab67c7":"पहली प्रकाशित रिलीज़: चरण 3 (बिना हाथ लगाए आवाज़ से नियंत्रण) और चरण 5 के निखार का सारा काम, Windows, macOS और Linux के लिए हस्ताक्षरित इंस्टॉलरों के रूप में तैयार।","changelog.880aaef19013":"<strong>एक मिनट का स्वागत परिचय</strong> (FT-50) — जब आप पहली बार ऐप खोलते हैं, चार छोटे चरण संपादक और उसके ठहराव-चिह्नों, गति के नियंत्रणों और प्रोजेक्टर से परिचय कराते हैं। इसे कभी भी छोड़ें, और जब चाहें <strong>सेटिंग्स → सामान्य → परिचय दोबारा दिखाएँ</strong> से फिर से चलाएँ।","changelog.0df57f3fd77c":"<strong>आपके सिस्टम के साथ चलने वाली थीम</strong> (FT-50) — गहरा और हल्का के साथ अब <strong>मेरे सिस्टम जैसी</strong> भी है, जो आपके OS के साथ बदलती है और सूर्यास्त पर आपकी मशीन के बदलते ही तुरंत नए रंग ले लेती है। डिफ़ॉल्ट अब भी गहरा है।","changelog.3d5dfaad60e5":"<strong>वॉइस कमांड</strong> (FT-30, FT-31) — <strong>चलाएँ, रोकें, तेज़, धीमा, अगला ठहराव, शुरुआत पर लौटें</strong> को अपनी आवाज़ में प्रशिक्षित करें (हर एक के कुछ टेक) और प्रॉम्प्टर को बिना हाथ लगाए चलाएँ। माइक्रोफ़ोन खुला होने पर हर बार एक साफ़ दिखने वाला <strong>● सुन रहा है</strong> संकेतक दिखता है; <strong>पुश-टू-टॉक</strong> (माइक सिर्फ़ तब खुला जब आप बटन दबाए रखें) या <strong>हमेशा सुनना</strong> चुनें। <strong>डिफ़ॉल्ट रूप से बंद।</strong> बिना मॉडल के: आपकी अपनी रिकॉर्डिंग से पारंपरिक सिग्नल प्रोसेसिंग द्वारा मिलान, डिवाइस पर ही।","changelog.689534aed982":"<strong>आवाज़ का अनुसरण</strong> (FT-32, FT-34, FT-35) — एक <strong>सिर्फ़ आपकी मर्ज़ी से चालू होने वाला</strong> मोड, जो आपके ज़ोर से पढ़ते समय स्क्रिप्ट को आपके साथ-साथ स्क्रॉल करता है, और साथ आए Apache-2.0 Vosk मॉडल से स्क्रिप्ट के अपने शब्द पहचानता है। जैसे ही यह आपकी जगह खो देता है, यह <strong>हटकर मैनुअल नियंत्रण को सौंप देता है</strong> (ताकि कभी ग़लत जगह स्क्रॉल न करे) और सिर्फ़ ऑपरेटर पूर्वावलोकन चलाता है, प्रोजेक्टर कभी नहीं। <strong>डिफ़ॉल्ट रूप से बंद</strong>, और जहाँ मॉडल इंस्टॉल नहीं है वहाँ कारण के साथ धूसर। निर्धारक संरेखण परत, जो तय करती है कि आप स्क्रिप्ट में कहाँ हैं, पूरी तरह हमारी अपनी है और यूनिट-टेस्ट की गई है।","changelog.10a2d92eba51":"<strong>इंस्टॉलर, हस्ताक्षरित और ख़ुद अपडेट होने वाले</strong> (FT-51, FT-52) — Windows (<code>.exe</code> और <code>.msi</code>), macOS यूनिवर्सल <code>.dmg</code>, और Linux AppImage और <code>.deb</code>, सभी एक ही टैग किए गए कमिट से बने। ऐप के भीतर का अपडेटर रिलीज़ पेज की जाँच करता है, और हर अपडेट को ऐप में मौजूद साइनिंग कुंजी से सत्यापित किया जाता है — जो अपडेट सत्यापित न हो सके, उसे इंस्टॉल करने के बजाय अस्वीकार कर दिया जाता है।","changelog.6831bb79a881":"<strong>कीबोर्ड और स्क्रीन-रीडर सुलभता की समीक्षा</strong> (FT-50) — फ़ोकस हो सकने वाला हर नियंत्रण अब एक साफ़ फ़ोकस रिंग दिखाता है; <strong>Tab</strong> खुले डायलॉग के भीतर ही रहता है, उसके पीछे की विंडो पर भटकता नहीं; डायलॉग बंद करने पर फ़ोकस उसी बटन पर लौटता है जिसने उसे खोला था; और सेटिंग्स की श्रेणी-सूची अब वही पैनल बताती है जिसे आप सचमुच देख रहे हैं, तब भी जब खोज उसे छाँट रही हो। ऐप हर जगह <strong>कम गति</strong> वाली सिस्टम सेटिंग का भी सम्मान करता है। स्क्रिप्ट का अपना स्क्रॉल जानबूझकर इस सेटिंग से अछूता रखा गया है — ऐप इसी के लिए है, और उसकी गति आप पहले से सीधे नियंत्रित करते हैं।","changelog.54a57c3147c4":"निजता","changelog.deae17e358ff":"<strong>कभी कोई नेटवर्क नहीं।</strong> वॉइस कमांड कभी नेटवर्क या डिस्क को नहीं छूते — ऑडियो का मिलान मेमोरी में आपकी अपनी रिकॉर्डिंग से होता है, और आपकी कही कोई भी बात फ़ाइल में नहीं लिखी जाती। आवाज़ का अनुसरण पहचानकर्ता को पूरी तरह डिवाइस पर ही चलाता है; मॉडल इंस्टॉलर के साथ आता है और चलते समय कुछ भी डाउनलोड नहीं करता।","changelog.0d7048033eef":"_<strong>इस बिल्ड में आवाज़ का अनुसरण उपयोग योग्य नहीं है।</strong> पहचानकर्ता को एक स्पीच मॉडल चाहिए, और यह रिलीज़ अभी कोई मॉडल साथ नहीं लाती — फ़ीचर इसे पहचान लेता है और चालू करने पर विफल होने के बजाय कारण सहित ख़ुद को अनुपलब्ध बताता है। वॉइस <strong>कमांड</strong> पर कोई असर नहीं: उन्हें किसी मॉडल की ज़रूरत नहीं और वे यहाँ काम करते हैं। नीचे की संरेखण और व्याकरण परतें पूरी हैं और परखी जा चुकी हैं।_","changelog.f8a8681a3de9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.300.0</span></span><span class=\"release__title\">22 जुलाई 2026</span>","changelog.49b18dafa9ac":"स्क्रिप्ट संपादक में ऑफ़लाइन ऑटोकम्प्लीट: टाइप करते समय यह शब्द का बाक़ी हिस्सा सुझाता है, 18 में से किसी भी भाषा में, उन शब्द-सूचियों से जो ऐप के भीतर ही आती हैं।","changelog.863ad5535d5a":"<strong>धुँधले पाठ वाला ऑटोकम्प्लीट</strong> (FT-20, FT-21) — कोई शब्द शुरू करें और उसका बाक़ी हिस्सा कर्सर के आगे धुँधला दिखाई देता है। <strong>Tab</strong> उसे स्वीकार करता है, <strong>Esc</strong> उसे हटा देता है, और सीधे टाइप करते जाने पर वह अनदेखा हो जाता है। शब्द पूरा करके स्पेस दबाने पर यह पूरे आम वाक्यांश भी पूरे करता है।","changelog.342d77799f0d":"<strong>ऑटोकम्प्लीट सेटिंग्स</strong> — एक नया <strong>संपादक</strong> पैनल, जिसमें चालू/बंद स्विच और अपनी अलग <strong>सुझावों की भाषा</strong> है, जो ऐप की भाषा से अलग है, क्योंकि एक भाषा में स्क्रिप्ट लिखना और दूसरी भाषा में ऐप चलाना आम बात है।","changelog.bf3195662b89":"<strong>सभी 18 भाषाओं के लिए शब्द और वाक्यांश तालिकाएँ</strong> (FT-22) — कुल मिलाकर लगभग 464,000 शब्द और 345,000 वाक्यांश, इंस्टॉलर में शामिल। सिर्फ़ वही भाषा लोड होती है जिसका आप सचमुच उपयोग कर रहे हैं, इसलिए ऐप को एक समय में पूरे 12 MB के बजाय लगभग 0.5 MB मेमोरी ही लगती है।","changelog.9fb2fa59ae13":"<strong>भाषा चुनने की सूची अब English से शुरू होती है और फिर हर भाषा के अपने नाम के वर्णक्रम में चलती है</strong> — Deutsch, Español, Français, इत्यादि — और ऐप चाहे किसी भी भाषा में हो, यही क्रम बना रहता है। पहले यह अंग्रेज़ी नामों के क्रम में थी, इसलिए आपने जो चुना हो उसके हिसाब से क्रम बदल जाता था।","changelog.6e805db44ddd":"<strong>ऑटोकम्प्लीट कभी नेटवर्क को नहीं छूता।</strong> यह इंस्टॉलर के भीतर की तालिकाओं में एक खोज भर है — न कोई मॉडल, न कोई सेवा, न कोई टेलीमेट्री। आप जो टाइप करते हैं वह कहीं नहीं भेजा जाता, और यह फ़ीचर मशीन के ऑफ़लाइन होने पर भी काम करता है।","changelog.97775eaa1065":"<span class=\"release__meta\"><span class=\"release__ver\">v0.200.0</span></span><span class=\"release__title\">21 जुलाई 2026</span>","changelog.fdaeb02ed57c":"स्टैंडअलोन टेलीप्रॉम्प्टर: स्क्रिप्ट जिन्हें आप सँभालकर रख सकें, प्रस्तुतकर्ता के लिए प्रोजेक्टर, असली ट्रांसपोर्ट, और ख़ुद को ज़ोर से पढ़कर सुनाता प्रॉम्प्टर।","changelog.3c1c1f577fc6":"<strong>स्क्रिप्ट लाइब्रेरी</strong> (FT-10) — <code>.ftscript</code> फ़ाइलें जिन्हें आप बना, खोल, नाम बदल और हटा सकते हैं, हाल की फ़ाइलों की सूची और टाइप करते समय <strong>ऑटोसेव</strong> के साथ। ये एक ही फ़ोल्डर में सादा UTF-8 पाठ हैं, इसलिए अगर यह ऐप कभी न रहे, तब भी किसी भी टेक्स्ट एडिटर में स्क्रिप्ट पढ़ी जा सकती है, उसकी तुलना की जा सकती है और उसे बचाया जा सकता है। ऐप वही फिर से खोलता है जो आपने पिछली बार खोला था।","changelog.54ba591e950e":"<strong>संपादक में ठहराव चिप</strong> (FT-11) — पंक्ति के भीतर का हर <code> -- </code> / <code> --2 </code> एक अविभाज्य गोली के रूप में दिखता है जो अपने ठहराव की लंबाई बताती है। कैरेट सिर्फ़ उसके पहले या बाद में रह सकता है, Backspace/Delete एक ही बार दबाने में पूरा टोकन हटा देता है, Shift+तीर उसे एक इकाई के रूप में चुनता है, कॉपी/कट असली <code> -- </code> पाठ ले जाते हैं, और पेस्ट की गई स्क्रिप्ट की बेतरतीब स्पेसिंग सामान्य कर दी जाती है। दूसरा डैश टाइप करते ही आपके लिए ठहराव बन जाता है।","changelog.b9587c13e3c6":"<strong>प्रोजेक्टर विंडो</strong> (FT-12) — पठन सतह को किसी भी जुड़े डिस्प्ले पर खोलें, किनारे से किनारे तक भरी हुई, बीम-स्प्लिटर प्रॉम्प्टर काँच के लिए <strong>दर्पण-उलटाव</strong> के साथ। यह ऑपरेटर पूर्वावलोकन वाली स्क्रॉल स्थिति से ही चलती है, इसलिए दोनों में कभी इस पर मतभेद नहीं हो सकता कि पाठ कहाँ पहुँचा है, और इसमें असल में पढ़ने वाले व्यक्ति के लिए अपना ट्रांसपोर्ट, सीक बार और कीबोर्ड शॉर्टकट हैं।","changelog.d50b42582cf9":"<strong>LAN मिरर</strong> (FT-12) — स्क्रॉल होती स्क्रिप्ट को अपने ही नेटवर्क के फ़ोन, टैबलेट या दूसरे लैपटॉप पर मिरर करें, उस लिंक और QR कोड से जो ऐप आपको दिखाता है। हर डिवाइस अपना फ़ॉन्ट आकार ख़ुद तय करता है, बिना यह बदले कि बाक़ी कोई क्या देखता है। <strong>डिफ़ॉल्ट रूप से बंद</strong>, जब तक आप इसे स्पष्ट रूप से नेटवर्क के लिए न खोलें तब तक सिर्फ़ लूपबैक पर, हर बार ऐप शुरू होने पर नई बनने वाली कुंजी से सुरक्षित, और <strong>केवल-पढ़ने के लिए</strong> — ब्राउज़र जो भी भेजे, उससे स्क्रॉल, स्क्रिप्ट या कोई सेटिंग नहीं बदल सकती।","changelog.00b57b5822cd":"<strong>असली ट्रांसपोर्ट</strong> (FT-13) — चलाएँ / रोकें / बंद करें / पीछे / आगे के लिए ठीक-ठाक SVG बटन, <strong>दबाए रखने पर दोहराव</strong> के साथ; YouTube जैसी सीक बार, जिसमें बीता हुआ और कुल पढ़ने का समय (ठहराव गिनकर) हो और किसी भी बिंदु के शब्द होवर करके देखे जा सकें; किसी शब्द पर क्लिक करके वहीं से शुरू करना; माउस व्हील से आगे-पीछे करना; और प्रोजेक्टर पर कीबोर्ड शॉर्टकट।","changelog.d3d56659d660":"<strong>BPM गति मोड</strong> (FT-14) — गति को प्रति सेकंड अक्षरों के रूप में पढ़ें, या संगीतमय प्रस्तुति के लिए <strong>BPM (20–250)</strong> के रूप में। इंजन पूरे समय अक्षर प्रति सेकंड में ही चलता है; BPM दिखाने और दर्ज करने का एक मोड है, और आप जो भी BPM टाइप कर सकते हैं वह इंजन की अपनी सीमा के भीतर ही पड़ता है, बजाय इसके कि वह आपकी जानकारी के बिना चुपचाप सीमित कर दिया जाए।","changelog.5fe2620dd908":"<strong>दिखावट के नियंत्रण</strong> (FT-15) — टाइपफ़ेस, मोटाई, पाठ का रंग, किनारों के मार्जिन, पंक्ति अंतराल, और स्क्रीन पर <strong>पठन रेखा कहाँ रहती है</strong>। ये किसी एक विंडो की स्थिति में नहीं, इंजन में रहते हैं, इसलिए पूर्वावलोकन, प्रोजेक्टर और LAN मिरर हमेशा एक जैसे दिखते हैं।","changelog.ca6865582cd0":"<strong>प्रति-OS वाक् संश्लेषण से ज़ोर से पढ़ें</strong> (FT-16) — टेक से पहले समय जाँचने के लिए प्रॉम्प्टर से स्क्रिप्ट को आपकी तय की गई गति पर पढ़वाएँ। हाइलाइट बोले जा रहे शब्द के साथ चलता है, ठहराव असली चुप्पी बन जाते हैं (<code>--</code> को कभी “डैश” नहीं बोला जाता), और आगे-पीछे जाने पर आवाज़ भी वहीं पहुँच जाती है। यह <strong>सिर्फ़ पूर्वावलोकन के लिए</strong> है: यह प्रस्तुतकर्ता के प्रोजेक्टर को कभी नहीं हिलाता। यह आपके OS में पहले से मौजूद आवाज़ों का उपयोग करता है (Windows OneCore/SAPI, macOS AVSpeechSynthesis, Linux Speech Dispatcher / espeak-ng) — कोई स्पीच इंजन साथ नहीं आता।","changelog.cdfbacda0108":"<strong>हर भाषा अब हर मशीन पर दिखती है।</strong> ऐप उन सभी 18 भाषाओं के लिए Noto फ़ॉन्ट साथ लाता है जिनमें वह उपलब्ध है — लैटिन, ग्रीक, सिरिलिक, वियतनामी, अरबी, देवनागरी, जापानी, कोरियाई और सरलीकृत चीनी। जिस मशीन पर कोई जापानी फ़ॉन्ट इंस्टॉल न हो, वहाँ जापानी चुनने पर पहले इंटरफ़ेस की जगह डिब्बे दिखते थे; अब ऐप वह सब साथ रखता है जिसकी उसे ज़रूरत है। चुनी गई भाषा असल में जिन अक्षर-उपसमूहों का उपयोग करती है, सिर्फ़ वही लोड होते हैं, और ये फ़ॉन्ट हर पठन टाइपफ़ेस के पीछे भी सहारा देते हैं, इसलिए “सेरिफ़” चुनने से कोई भाषा कभी अपठनीय नहीं हो सकती। फ़ॉन्ट SIL Open Font License के तहत हैं; इसकी सूचना ऐप के साथ <code>THIRD-PARTY.md</code> के रूप में आती है।","changelog.d1589cdefe34":"<strong>ऐप अपनी विंडो ख़ुद बनाता है।</strong> OS की कोई शीर्षक पट्टी नहीं: बीच में शीर्षक, और दाईं ओर सेटिंग्स, परिचय, और छोटा करें / बड़ा करें-पहले जैसा करें / बंद करें — वही व्यवस्था जो Freally Player में है, ताकि पूरे सूट की विंडो एक जैसी लगें। पट्टी को खींचा जा सकता है, डबल-क्लिक अब भी बड़ा करता है, और विंडो का आकार अब भी हर किनारे और कोने से बदला जा सकता है।","changelog.83b865a057ab":"<strong>सेटिंग्स अब एक ठीक-ठाक सेटिंग्स डायलॉग है</strong>, Freally Capture जैसी ही बनावट में: खोज बॉक्स के साथ श्रेणियों की साइडबार (सामान्य, पठन, दिखावट, प्रोजेक्टर, नेटवर्क), और नीचे <strong>ठीक है / रद्द करें / लागू करें</strong>। जब तक कुछ सचमुच न बदले, लागू करें निष्क्रिय रहता है, और एक बिंदु उन श्रेणियों को चिह्नित करता है जिन्हें आपने बदला है पर अभी लागू नहीं किया।","changelog.dd1a689ff484":"<strong>सिस्टम ट्रे में छोटा करें</strong> (सेटिंग्स → सामान्य)। डिफ़ॉल्ट रूप से बंद। इसे चालू करने पर छोटा करना विंडो को छिपा देता है और ट्रे में एक आइकॉन रख देता है; वापस लाने पर विंडो लौट आती है <strong>और आइकॉन हट जाता है</strong> — ऐप या तो टास्कबार में होता है या ट्रे में, दोनों में कभी नहीं। ट्रे मेनू का अनुवाद बाक़ी ऐप की तरह ही होता है।","changelog.4124706702a9":"<strong>ऐप आइकॉन अब हर आकार में पूरा आर्टवर्क है।</strong> <code>0.100.0</code> ने 48px और उससे छोटे आइकॉन के लिए एक कटा हुआ, सिर्फ़ ग्लिफ़ वाला “F” लगा दिया था, इस आधार पर कि आर्टवर्क का वर्डमार्क इतने छोटे आकार में पढ़ा नहीं जा सकता। पता चला कि पढ़ने योग्य पर अलग निशान से ज़्यादा एक जैसा निशान मायने रखता है, इसलिए कटा हुआ रूप हटा दिया गया — टास्कबार, ट्रे और फ़ेविकॉन सब अब एक ही आइकॉन दिखाते हैं।","changelog.c347bd2b4305":"इस चरण की समीक्षा में, रिलीज़ से पहले पकड़े गए:","changelog.47424533ef57":"<strong>ठहराव चिप वहाँ दिख सकती थी जहाँ प्रॉम्प्टर कोई ठहराव नहीं लेता था।</strong> संपादक और ज़ोर से पढ़ना, दोनों के पास <code> -- </code> व्याकरण की अपनी-अपनी प्रति थी, उन सीमाओं के बिना जो स्क्रॉल इंजन लागू करता है — इसलिए <code>--2.5.3</code> को ऐसे ठहराव के रूप में दिखाया जाता था जिसे प्रॉम्प्टर सीधे पार कर जाता। अब तीनों एक ही स्कैनर साझा करते हैं।","changelog.b434155bb7d9":"<strong>ट्रे आइकॉन पर राइट-क्लिक करने से विंडो वापस आ जाती थी</strong>, मेनू नहीं खुलता था, जिससे ट्रे का अपना “बाहर निकलें” पहुँच से बाहर हो जाता था।","changelog.ec0cf2fce1a1":"अब जब ऐप अपनी शीर्षक पट्टी ख़ुद बनाता है, <strong>पहली बार चलने पर दिखने वाले अनुबंध के बटन विंडो के निचले किनारे से नीचे जा सकते थे</strong>।","changelog.9d5731455d75":"<strong>सेटिंग्स ऐसा मान दिखा सकती थीं जिसका ऐप उपयोग नहीं कर रहा था।</strong> जिस संख्या को बैकएंड सीमित कर देता (मान लीजिए 1024 से कम कोई पोर्ट), वह अगले रीस्टार्ट तक वही दिखती रहती थी जो टाइप की गई थी; अब डायलॉग वही दिखाता है जो असल में सहेजा गया।","changelog.db89654f4e78":"<strong>सेटिंग्स में खोजने से स्क्रीन पर ग़लत पैनल रह सकता था</strong>, और उसे समझाने के लिए कोई श्रेणी हाइलाइट नहीं होती थी।","changelog.39ed54f3671f":"<strong>रोकना अब इंजन में एक ही क्रिया है</strong>, न कि हर बटन द्वारा जोड़ी गई “रोकें और पीछे जाएँ” की जोड़ी, इसलिए स्क्रॉल रोकने वाली कोई भी दूसरी चीज़ भी वैसा ही व्यवहार करती है।","changelog.e806a291cfc3":"परीक्षण","changelog.b6521470f6ed":"<strong>Playwright अब चरण 1 के हर उस फ़ीचर को परखता है जहाँ तक वह पहुँच सकता है</strong> — स्क्रिप्ट लाइब्रेरी का पूरा जीवनचक्र, चिप का व्यवहार, डिस्प्ले चुनने वाला, ट्रांसपोर्ट, BPM रूपांतरण, दिखावट की पाइपलाइन, और यह अनुबंध कि ज़ोर से पढ़ना साझा स्क्रॉल को कभी नहीं छूता। नकली ब्रिज IPC कॉल दर्ज करता है, इसलिए टेस्ट यह जाँचते हैं कि UI ने बैकएंड से असल में क्या करने को कहा।","changelog.965a9f5ce8e2":"<strong>हर CI रन में ऐप अब Windows, macOS और Linux पर चलाया जाता है और उसकी तस्वीर ली जाती है</strong> (<code>scripts/app-screenshot.mjs</code>), और अगर वह शुरू होते ही बंद हो जाए या कुछ भी न दिखाए तो रन विफल होता है। सफल कंपाइल और दिखने वाला वेबव्यू दो अलग बातें हैं।","changelog.33678f48d52f":"<strong>हर भाषा को सिर्फ़ स्ट्रिंग्स के लिए नहीं, पठनीयता के लिए भी जाँचा जाता है।</strong> एक टेस्ट ऐप को 18 में से हर लोकेल में बदलता है और साबित करता है कि उसके अपने इंटरफ़ेस का हर अक्षर साथ आए किसी फ़ॉन्ट में मौजूद है। कोई लिपि न हो तो वह डिब्बों के रूप में दिखती है, जो स्क्रीनशॉट और बाक़ी हर जाँच को सही पाठ जैसी लगती है — इसलिए अरबी, हिन्दी, जापानी, कोरियाई और चीनी में से हर एक चुपचाप टूट सकती थी, और सिर्फ़ उन लोगों के लिए जो उन्हें पढ़ते हैं।","changelog.503e7e57035d":"<strong>जो अनुवाद चुपचाप अंग्रेज़ी पर लौट आए, वह अब बिल्ड को विफल कर देता है।</strong> थोक अनुवाद जिन चीज़ों का अनुवाद नहीं कर पाते, उनके लिए अंग्रेज़ी छोड़ देते हैं, और नतीजा पार्स भी हो जाता है और पूरा दिखते हुए रिलीज़ भी हो जाता है। असली अपवाद — “OK”, “Port”, व्यक्तिवाचक नाम — कारण सहित सूचीबद्ध हैं।","changelog.8b79c1c1b492":"<strong>Linux पर रेंडरिंग अब मानी नहीं जाती, साबित की जाती है।</strong> CI स्क्रीनशॉट एक सॉफ़्टवेयर रेंडरर वाले कंटेनर में चलता है, क्योंकि GitHub के सादे Linux रनर पर कोई काम करता GL नहीं है और वह ख़ाली विंडो ही बनाता था, ऐप ठीक हो या न हो — जो जाँच कभी विफल ही न हो सके, वह हमें कुछ नहीं बता रही थी।","changelog.bf256044a419":"जो कुछ सचमुच स्वचालित नहीं किया जा सकता — दूसरा मॉनिटर, प्रॉम्प्टर काँच, सुनाई देने वाली आवाज़, आपके वाई-फ़ाई पर कोई फ़ोन — उन सबके लिए अब <code>Live-To-Do-List.md</code> में <strong>चरण-दर-चरण अभ्यास</strong> हैं।","changelog.8a7525b1492f":"टिप्पणियाँ","changelog.f38acbd9b28b":"<strong>अब भी कोई AI नहीं, कोई खाता नहीं, कोई टेलीमेट्री नहीं।</strong> LAN मिरर आपकी स्क्रिप्ट उन्हीं डिवाइसों तक पहुँचाता है जिन्हें आप उससे जोड़ते हैं, आपके अपने नेटवर्क पर; कुछ भी अपलोड या आगे रिले नहीं होता। ऐप का इकलौता बाहर जाने वाला अनुरोध अब भी अपडेट की जाँच ही है।","changelog.aadc02e8de62":"<span class=\"release__meta\"><span class=\"release__ver\">v0.100.0</span></span><span class=\"release__title\">21 जुलाई 2026</span>","changelog.7bfe7961d71b":"ढाँचे का चरण: ऐप अब बिल्ड होता है, चलता है, और अनुबंध स्वीकार होने तक आगे नहीं बढ़ने देता, साथ में Freally Capture से लाया गया अक्षर-आधारित स्क्रॉल इंजन।","changelog.19bd3024e088":"<strong>Tauri v2 ढाँचा</strong> (FT-00) — एक Rust वर्कस्पेस (<code>src-tauri</code>) और एक React/TypeScript UI (<code>ui</code>), जो Freally Capture जैसी ही टूलिंग बनावट साझा करते हैं: <code>ci.yml</code>, <code>scripts/ci-local.mjs</code>, <code>deny.toml</code>, और एक पिन किया हुआ <code>rust-toolchain.toml</code>, ताकि <code>npm run ci:local</code> पहले ही दिन से पूरी जाँच चलाए।","changelog.045988032f64":"<strong>आइकॉन सेट</strong> (FT-01) — मूल आर्टवर्क से <code>scripts/make-icons.py</code> द्वारा बनाया गया, Windows, macOS और Linux के लिए, साथ में वेबसाइट के फ़ेविकॉन भी। 48px या उससे छोटे आकार <strong>सिर्फ़ ग्लिफ़ वाले “F”</strong> रूप का उपयोग करते हैं, क्योंकि आर्टवर्क में जड़ा वर्डमार्क 64px से छोटा होने पर पढ़ा नहीं जा सकता (मापा गया, अनुमान नहीं)।","changelog.e0471332722d":"<strong>अक्षर-आधारित टेलीप्रॉम्प्टर इंजन</strong> (FT-02) — <code>teleprompter.rs</code> और उसका TypeScript जुड़वाँ <code>ui/src/lib/caesura.ts</code>, Freally Capture से लाए गए: दिखने वाले अक्षरों पर आधारित स्क्रॉल ऑफ़सेट, पंक्ति के भीतर <code> -- </code> ठहराव (मनचाहे ठहराव के लिए <code> --2 </code>), आगे-पीछे जाने, कदम और गति के नियंत्रण, और शुरू होने से पहले काउंटडाउन वाला प्री-रोल। पूर्वावलोकन और प्रोजेक्टर पाठ को एक ही तय-चौड़ाई वाले मंच पर रखते हैं और CSS से उसका आकार बदलते हैं, इसलिए दोनों ठीक एक ही कॉलम पर पंक्ति तोड़ते हैं।","changelog.a1b0c9f8ea89":"<strong>एक-विंडो वाला ऐप ढाँचा</strong> (FT-03) — टूलबार, स्क्रिप्ट इनपुट, और लाइव प्रॉम्प्टर सतह, साथ में ड्राफ़्ट/लागू करें पैटर्न पर चलने वाली <strong>सेटिंग्स</strong> (लागू करें दबाने तक कुछ भी असर नहीं करता; रद्द करें ठीक वही लौटा देता है जो आपके पास था) और <strong>18 लोकेल</strong> वाली, Fluent पर आधारित अनुवाद की नींव।","changelog.b45c55ac02ea":"<strong>डॉक्स साइट + बदलाव लॉग</strong> (FT-04) — साइट <code>/docs</code> से GitHub Pages द्वारा परोसी जाती है, बाक़ी Freally ऐप्स की तरह।","changelog.8b96bdf6151d":"<strong>पहली बार चलने पर EULA की शर्त</strong> (FT-05) — अनुबंध स्वीकार होने तक ऐप का उपयोग नहीं किया जा सकता। स्वीकृति का संस्करण दर्ज होता है और वह <strong>सेटिंग्स के हर बार सहेजे जाने पर बनी रहती है</strong> (यह बग Freally Capture में रिलीज़ हो गया था; अब इसके लिए एक रिग्रेशन टेस्ट है)।","changelog.d5361112a7c1":"<strong>समस्या रिपोर्टर और अपडेट जाँच</strong> — Havoc मानक वाला क्रैश रिपोर्टर (साफ़ की गई स्थानीय रिपोर्ट, सिस्टम की अपनी “अचानक बंद हो गया” सूचना, रीस्टार्ट, और GitHub/Gmail/ईमेल से भेजना, जिसे आप ख़ुद शुरू करते हैं) और ऐप शुरू होते समय अपडेट की जाँच, जो कुछ भी करने से पहले संस्करण और असली रिलीज़ नोट्स दिखाती है।","changelog.198e4f9204b8":"<strong>कोई AI नहीं, कोई खाता नहीं, कोई टेलीमेट्री नहीं।</strong> इकलौता बाहर जाने वाला अनुरोध अपडेट की जाँच है; वह आपके, आपकी मशीन के या आपकी स्क्रिप्टों के बारे में कुछ नहीं भेजता।","changelog.04d59a3b7905":"रिलीज़ पाइपलाइन आने तक साइट पर डाउनलोड लिंक सिर्फ़ प्लेसहोल्डर हैं।","changelog.a3c71b90162b":"ज्ञात सीमाएँ","changelog.4d18eba61c3f":"<strong>अभी कोई इंस्टॉलर नहीं है।</strong> <code>0.100.0</code> सोर्स कोड का एक पड़ाव है; हस्ताक्षरित, हर OS के लिए अलग रिलीज़ पाइपलाइन बाद का चरण है।","changelog.57871c6e9623":"<strong>स्वचालित अपडेट सक्रिय नहीं हैं।</strong> अपडेटर अपनी साइनिंग सार्वजनिक कुंजी के बिना आता है, इसलिए वह किसी असत्यापित पैकेज को इंस्टॉल करने के बजाय हर पैकेज को अस्वीकार कर देता है — वह सुरक्षित ढंग से विफल होता है, पर सफल भी नहीं हो सकता। कोड साइनिंग आने तक “अपडेट जाँचें” एक त्रुटि बताएगा।"};
